window.AUTH=window.AUTH||{};window.AUTH["20-1312"]={"d":"20-1312","id":"2021/20-1312","n":"Becerra v. Empire Health Foundation","briefs":[{"k":"petitioner","label":"Brief of petitioner Becerra, Xavier, Secretary of Health and Human Services","date":"2021-09-01","url":"https://www.supremecourt.gov/DocketPDF/20/20-1312/190165/20210901163343282_20-1312tsUnitedStates.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent Empire Health Foundation, for Valley Hospital Medical Center","date":"2021-10-18","url":"https://www.supremecourt.gov/DocketPDF/20/20-1312/196722/20211018160219039_2021-10-18%20Empire%20Merits%20Brief%20FINAL.pdf","side":"res","n":81},{"k":"reply","label":"Reply of petitioner Becerra, Xavier, Secretary of Health and Human Services","date":"2021-11-17","url":"https://www.supremecourt.gov/DocketPDF/20/20-1312/200264/20211117141948708_20-1312rbUnitedStates.pdf","side":"pet","n":51}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/597us1r59_i4dk.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"37","2":"15"}},{"t":"case","label":"Bowen v. Galbreath","cite":"485 U.S. 74","y":1988,"id":"1987/86-1146","sc":1,"op":1,"sum":"A district court does not have the authority to order the Secretary to withhold a portion of past-due SSI benefits for the payment of attorney's fees received in judicial proceedings under Title XVI. Pp. 75-79. 799 F. 2d 370, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Cabell Huntington Hosp., Inc. v. Shalala","cite":"101 F.3d 984","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/101/984/","by":{"0":"5, 12, 13, 33, 47","1":"passim"}},{"t":"case","label":"Catholic Health Initiatives Iowa Corp. v. Sebelius","cite":"718 F.3d 914","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/718/914/","op":2,"by":{"0":"passim","1":"20"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"ar":13,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"20, 23, 26, 42","2":"21"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Deaconess Health Servs. Corp. v. Shalala: 912 F. Supp. 438 (E.D. Mo. 1995), aff ’d","cite":"83 F.3d 1041","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/83/1041/","by":{"0":"13","1":"12, 36"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"0":"27, 46","2":"4"}},{"t":"case","label":"Edgewater Med. Ctr. v. Blue Cross & Blue Shield Ass’n, HCFA Adm’r Dec. (PRRB Dec. Nos. 2000-D44 & 2000-D45)","cite":"2000 WL 1146601","y":2000,"court":"June 19","ar":1,"by":{"0":"4, 12"}},{"t":"case","label":"Entergy Corp. v. Riverkeeper, Inc.","cite":"556 U.S. 208","y":2009,"id":"2008/07-588","sc":1,"sum":"The Court found that the Environmental Protection Agency (EPA) was permitted to use a cost-benefit analysis while setting national performance standards for cooling water intake structures.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Good Samaritan Hosp. v. Shalala","cite":"508 U.S. 402","y":1993,"id":"1992/91-2079","sc":1,"sum":"Title 42 U. S. C. § 1395f(b)(1) requires the Secretary of Health and Human Services to reimburse the lesser of the \"customary charges\" or the \"reasonable cost[s]\" of providers of health care services to Medicare beneficiaries, while § 1395x(v)(1)(A) empowers the Secretary to issue regulations setting forth the methods to be used in computing reasonable costs, which may include the establishment of appropriate cost …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"Hall v. Sebelius","cite":"667 F.3d 1293","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/667/1293/","op":1,"by":{"0":"28"}},{"t":"case","label":"Holder v. Martinez Gutierrez","cite":"566 U.S. 583","y":2012,"id":"2011/10-1542","sc":1,"sum":"The Court held that an unemancipated minor cannot use his or her parent's years of residency to fulfill the requirements for having a removal from the country stayed under 8 U.S. C. 1229(a).","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Jewish Hosp., Inc. v. Secretary of HHS","cite":"19 F.3d 270","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/19/270/","sum":"Observing that the final version was “hashed out in conference,” but also tracked an earlier Senate proposal.","sumSrc":"brief:0","by":{"0":"3, 6, 7, 13, 33, 38","1":"passim"}},{"t":"case","label":"Legacy Emanuel Hosp. & Health Ctr. v. Shalala","cite":"97 F.3d 1261","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/97/1261/","by":{"0":"12, 13, 20, 33, 45","1":"passim"}},{"t":"case","label":"MSP Recovery Claims, Series LLC v. ACE Am. Ins. Co.","cite":"974 F.3d 1305","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/1305/","by":{"0":"11"}},{"t":"case","label":"Maine Med. Ctr. v. Burwell","cite":"841 F.3d 10","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/841/10/","by":{"0":"2, 3"}},{"t":"case","label":"Metropolitan Hosp. v. United States Dep’t of HHS","cite":"712 F.3d 248","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/712/248/","op":2,"by":{"0":"3, 5, 21, 42","1":"20","2":"10"}},{"t":"case","label":"Monmouth Med. Ctr. v. Thompson","cite":"257 F.3d 807","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/257/807/","by":{"0":"12, 13"}},{"t":"case","label":"Northeast Hosp. Corp. v. Sebelius","cite":"657 F.3d 1","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/657/1/","op":2,"by":{"0":"passim","1":"passim","2":"9, 12"}},{"t":"case","label":"Obduskey v. McCarthy & Holthus LLP","cite":"139 S. Ct. 1029","y":2019,"id":"2018/17-1307","sc":1,"sum":"A business engaged in no more than nonjudicial foreclosure proceedings is not a “debt collector” under the Fair Debt Collection Practices Act, except for the limited purpose of enforcing security interests under 15 U. S. C. §1692f(6).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"sum":"The Court held that the reaudit rule is a reasonable interpretation of the GME Amendment and that it is not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Rhode Island Hosp. v. Leavitt","cite":"548 F.3d 29","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/548/29/","by":{"0":"3, 4"}},{"t":"case","label":"Samaritan Health Ctr. v. Heckler","cite":"636 F. Supp. 503","y":1985,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./636/503/","by":{"0":"4","1":"8"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"passim","2":"8, 17"}},{"t":"case","label":"United Sav. Ass’n v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36, 37"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/159","by":{"0":"5","1":"8"}},{"t":"law","label":"Pub. L. No. 98-369","url":"https://www.govinfo.gov/link/statute/98/1080","by":{"0":"5","1":"8"}},{"t":"law","label":"Health Insurance for the Aged Act, Pub. L. No. 89-97","url":"https://www.govinfo.gov/link/statute/79/290","by":{"0":"28"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"0":"28"}},{"t":"usc","label":"42 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/42/402","by":{"0":"28"}},{"t":"usc","label":"42 U.S.C. § 426","url":"https://www.law.cornell.edu/uscode/text/42/426","subs":["(1965)","(a)","(b)","(c)(1)"],"stext":{"head":"§426. Entitlement to hospital insurance benefits","paras":[[0,"(a) Individuals over 65 years"],[0,"Every individual who—"],[1,"(1) has attained age 65, and"],[1,"(2)(A) is entitled to monthly insurance benefits under section 402 of this title, would be entitled to those benefits except that he has not filed an application therefor (or application has not been made for a benefit the entitlement to which for any individual is a condition of entitlement therefor), or would be entitled to such benefits but for the failure of another individual, who meets all the criteria of entitlement to monthly insurance benefits, to meet such criteria throughout a month, and, in conformity with regulations of the Secretary, files an application for hospital insurance benefits under part A of subchapter XVIII,"],[1,"(B) is a qualified railroad retirement beneficiary, or"],[1,"(C)(i) would meet the requirements of subparagraph (A) upon filing application for the monthly insurance benefits involved if medicare qualified government employment (as defined in section 410(p) of this title) were treated as employment (as defined in section 410(a) of this title) for purposes of this subchapter, and (ii) files an application, in conformity with regulations of the Secretary, for hospital insurance benefits under part A of subchapter XVIII,"],[0,"shall be entitled to hospital insurance benefits under part A of subchapter XVIII for each month for which he meets the condition specified in paragraph (2), beginning with the first month after June 1966 for which he meets the conditions specified in paragraphs (1) and (2)."],[0,"(b) Individuals under 65 years"],[0,"Every individual who—"],[1,"(1) has not attained age 65, and"],[1,"(2)(A) is entitled to, and has for 24 calendar months been entitled to, (i) disability insurance benefits under section 423 of this title or (ii) child's insurance benefits under section 402(d) of this title by reason of a disability (as defined in section 423(d) of this title) or (iii) widow's insurance benefits under section 402(e) of this title or widower's insurance benefits under section 402(f) of this title by reason of a disability (as defined in section 423(d) of this title), or"],[1,"(B) is, and has been for not less than 24 months, a disabled qualified railroad retirement beneficiary, within the meaning of section 231f(d) of title 45, or"],[1,"(C)(i) has filed an application, in conformity with regulations of the Secretary, for hospital insurance benefits under part A of subchapter XVIII pursuant to this subparagraph, and"],[1,"(ii) would meet the requirements of subparagraph (A) (as determined under the disability criteria, including reviews, applied under this subchapter), including the requirement that he has been entitled to the specified benefits for 24 months, if—"],[2,"(I) medicare qualified government employment (as defined in section 410(p) of this title) were treated as employment (as defined in section 410(a) of this title) for purposes of this subchapter, and"],[2,"(II) the filing of the application under clause (i) of this subparagraph were deemed to be the filing of an application for the disability-related benefits referred to in clause (i), (ii), or (iii) of subparagraph (A),"],[0,"shall be entitled to hospital insurance benefits under part A of subchapter XVIII for each month beginning with the later of (I) July 1973 or (II) the twenty-fifth month of his entitlement or status as a qualified railroad retirement beneficiary described in paragraph (2), and ending (subject to the last sentence of this subsection) with the month following the month in which notice of termination of such entitlement to benefits or status as a qualified railroad retirement beneficiary described in paragraph (2) is mailed to him, or if earlier, with the month before the month in which he attains age 65. In applying the previous sentence in the case of an individual described in paragraph (2)(C), the \"twenty-fifth month of his entitlement\" refers to the first month after the twenty-fourth month of entitlement to specified benefits referred to in paragraph (2)(C) and \"notice of termination of such entitlement\" refers to a notice that the individual would no longer be determined to be entitled to such specified benefits under the conditions described in that paragraph. For purposes of this subsection, an individual who has had a period of trial work which ended as provided in section 422(c)(4)(A) of this title, and whose entitlement to benefits or status as a qualified railroad retirement beneficiary as described in paragraph (2) has subsequently terminated, shall be deemed to be entitled to such benefits or to occupy such status (notwithstanding the termination of such entitlement or status) for the period of consecutive months throughout all of which the physical or mental impairment, on which such entitlement or status was based, continues, and throughout all of which such individual would have been entitled to monthly insurance benefits under this subchapter or as a qualified railroad retirement beneficiary had such individual been unable to engage in substantial gainful activity, but not in excess of 78 such months. In determining when an individual's entitlement or status terminates for purposes of the preceding sentence, the term \"36 months\" in the second sentence of section 423(a)(1) of this title, in section 402(d)(1)(G)(i) of this title, in the last sentence of section 402(e)(1) of this title, and in the last sentence of section 402(f)(1) of this title shall be applied as though it read \"15 months\"."],[0,"(c) Conditions"],[0,"For purposes of subsection (a)—"],[1,"(1) entitlement of an individual to hospital insurance benefits for a month shall consist of entitlement to have payment made under, and subject to the limitations in, part A of subchapter XVIII on his behalf for inpatient hospital services, post-hospital extended care services, and home health services (as such terms are defined in part E of subchapter XVIII) furnished him in the United States (or outside the United States in the case of inpatient hospital services furnished under the conditions described in section 1395f(f) of this title) during such month; except that (A) no such payment may be made for post-hospital extended care services furnished before January 1967, and (B) no such payment may be made for post-hospital extended care services unless the discharge from the hospital required to qualify such services for payment under part A of subchapter XVIII occurred (i) after June 30, 1966, or on or after the first day of the month in which he attains age 65, whichever is later, or (ii) if he was entitled to hospital insurance benefits pursuant to subsection (b), at a time when he was so entitled; and"],[1,"(2) an individual shall be deemed entitled to monthly insurance benefits under section 402 or section 423 of this title, or to be a qualified railroad retirement beneficiary, for the month in which he died if he would have been entitled to such benefits, or would have been a qualified railroad retirement beneficiary, for such month had he died in the next month."],[0,"(d) \"Qualified railroad retirement beneficiary\" defined"],[0,"For purposes of this section, the term \"qualified railroad retirement beneficiary\" means an individual whose name has been certified to the Secretary by the Railroad Retirement Board under section 231f(d) of title 45. An individual shall cease to be a qualified railroad retirement beneficiary at the close of the month preceding the month which is certified by the Railroad Retirement Board as the month in which he ceased to meet the requirements of section 231f(d) of title 45."],[0,"(e) Benefits for widows and widowers"],[0,"(1)(A) For purposes of determining entitlement to hospital insurance benefits under subsection (b) in the case of widows and widowers described in paragraph (2)(A)(iii) thereof—"],[1,"(i) the term \"age 60\" in sections 402(e)(1)(B)(ii), 402(e)(4), 402(f)(1)(B)(ii), and 402(f)(4) of this title shall be deemed to read \"age 65\"; and"],[1,"(ii) the phrase \"before she attained age 60\" in the matter following subparagraph (F) of section 402(e)(1) of this title and the phrase \"before he attained age 60\" in the matter following subparagraph (F) of section 402(f)(1) of this title shall each be deemed to read \"based on a disability\"."],[0,"(B) For purposes of subsection (b)(2)(A)(iii), each month in the period commencing with the first month for which an individual is first eligible for supplemental security income benefits under subchapter XVI, or State supplementary payments of the type referred to in section 1382e(a) of this title (or payments of the type described in section 212(a) of Public Law 93–66) which are paid by the Secretary under an agreement referred to in section 1382e(a) of this title (or in section 212(b) of Public Law 93–66), shall be included as one of the 24 months for which such individual must have been entitled to widow's or widower's insurance benefits on the basis of disability in order to become entitled to hospital insurance benefits on that basis."],[0,"(2) For purposes of determining entitlement to hospital insurance benefits under subsection (b) in the case of an individual under age 65 who is entitled to benefits under section 402 of this title, and who was entitled to widow's insurance benefits or widower's insurance benefits based on disability for the month before the first month in which such individual was so entitled to old-age insurance benefits (but ceased to be entitled to such widow's or widower's insurance benefits upon becoming entitled to such old-age insurance benefits), such individual shall be deemed to have continued to be entitled to such widow's insurance benefits or widower's insurance benefits for and after such first month."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/426?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":3,"head":"§426. Entitlement to hospital insurance benefits","tname":"The Public Health and Welfare","by":{"0":"28, 29, 30, 6, 7, 6, 7, 6, 7, 6, 7","1":"32, 37, 38","2":"8, 9, 1, 2, 5, 8, 10, 18, 1, 2, 5, 8, 10, 18, 2, 3, 5, 13"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","by":{"0":"6, 7"}},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","stext":{"head":"§1395. Prohibition against any Federal interference","paras":[[0,"Nothing in this subchapter shall be construed to authorize any Federal officer or employee to exercise any supervision or control over the practice of medicine or the manner in which medical services are provided, or over the selection, tenure, or compensation of any officer or employee of any institution, agency, or person providing health services; or to exercise any supervision or control over the administration or operation of any such institution, agency, or person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395?type=usc&year=mostrecent&link-type=html"},"head":"§1395. Prohibition against any Federal interference","tname":"The Public Health and Welfare","by":{"0":"2, 28","2":"5"}},{"t":"usc","label":"42 U.S.C. § 1395b-2","url":"https://www.law.cornell.edu/uscode/text/42/1395b-2","subs":["(a)(2)","(a)"],"stext":{"head":"§1395b–2. Notice of medicare benefits; medicare and medigap information","paras":[[0,"(a) Notice of medicare benefits"],[0,"The Secretary shall prepare (in consultation with groups representing the elderly and with health insurers) and provide for distribution of a notice containing—"],[1,"(1) a clear, simple explanation of the benefits available under this subchapter and the major categories of health care for which benefits are not available under this subchapter,"],[1,"(2) the limitations on payment (including deductibles and coinsurance amounts) that are imposed under this subchapter, and"],[1,"(3) a description of the limited benefits for long-term care services available under this subchapter and generally available under State plans approved under subchapter XIX."],[0,"Such notice shall be mailed annually to individuals entitled to benefits under part A or part B of this subchapter and when an individual applies for benefits under part A or enrolls under part B."],[0,"(b) Medicare and medigap information"],[0,"The Secretary shall provide information via a toll-free telephone number on the programs under this subchapter. The Secretary shall provide, through the toll-free telephone number 1–800–MEDICARE, for a means by which individuals seeking information about, or assistance with, such programs who phone such toll-free number are transferred (without charge) to appropriate entities for the provision of such information or assistance. Such toll-free number shall be the toll-free number listed for general information and assistance in the annual notice under subsection (a) instead of the listing of numbers of individual contractors."],[0,"(c) Contents of notice"],[0,"The notice provided under subsection (a) shall include—"],[1,"(1) a statement which indicates that because errors do occur and because medicare fraud, waste, and abuse is a significant problem, beneficiaries should carefully check any explanation of benefits or itemized statement furnished pursuant to section 1395b–7 of this title for accuracy and report any errors or questionable charges by calling the toll-free phone number described in paragraph (4);"],[1,"(2) a statement of the beneficiary's right to request an itemized statement for medicare items and services (as provided in section 1395b–7(b) of this title);"],[1,"(3) a description of the program to collect information on medicare fraud and abuse established under section 1395b–5(b) of this title; and"],[1,"(4) a toll-free telephone number maintained by the Inspector General in the Department of Health and Human Services for the receipt of complaints and information about waste, fraud, and abuse in the provision or billing of services under this subchapter."],[0,"(d) Medicare opioid safety education"],[0,"The notice provided under subsection (a) shall include—"],[1,"(1) references to educational resources regarding opioid use and pain management;"],[1,"(2) a description of categories of alternative, non-opioid pain management treatments covered under this subchapter; and"],[1,"(3) a suggestion for the beneficiary to talk to a physician regarding opioid use and pain management."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395b-2?type=usc&year=mostrecent&link-type=html"},"head":"§1395b–2. Notice of medicare benefits; medicare and medigap information","tname":"The Public Health and Welfare","by":{"0":"2","1":"42, 43","2":"6"}},{"t":"usc","label":"42 U.S.C. § 1395c","url":"https://www.law.cornell.edu/uscode/text/42/1395c","stext":{"head":"§1395c. Description of program","paras":[[0,"The insurance program for which entitlement is established by sections 426 and 426–1 of this title provides basic protection against the costs of hospital, related post-hospital, home health services, and hospice care in accordance with this part for (1) individuals who are age 65 or over and are eligible for retirement benefits under subchapter II of this chapter (or would be eligible for such benefits if certain government employment were covered employment under such subchapter) or under the railroad retirement system, (2) individuals under age 65 who have been entitled for not less than 24 months to benefits under subchapter II of this chapter (or would have been so entitled to such benefits if certain government employment were covered employment under such subchapter) or under the railroad retirement system on the basis of a disability, and (3) certain individuals who do not meet the conditions specified in either clause (1) or (2) but who are medically determined to have end stage renal disease."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395c?type=usc&year=mostrecent&link-type=html"},"head":"§1395c. Description of program","tname":"The Public Health and Welfare","by":{"0":"2","2":"passim"}},{"t":"usc","label":"42 U.S.C. § 1395d","url":"https://www.law.cornell.edu/uscode/text/42/1395d","subs":["(a)","(b)"],"stext":{"head":"§1395d. Scope of benefits","paras":[[0,"(a) Entitlement to payment for inpatient hospital services, post-hospital extended care services, home health services, and hospice care"],[0,"The benefits provided to an individual by the insurance program under this part shall consist of entitlement to have payment made on his behalf or, in the case of payments referred to in section 1395f(d)(2) of this title to him (subject to the provisions of this part) for—"],[1,"(1) inpatient hospital services or inpatient critical access hospital services for up to 150 days during any spell of illness minus 1 day for each day of such services in excess of 90 received during any preceding spell of illness (if such individual was entitled to have payment for such services made under this part unless he specifies in accordance with regulations of the Secretary that he does not desire to have such payment made);"],[1,"(2)(A) post-hospital extended care services for up to 100 days during any spell of illness, and (B) to the extent provided in subsection (f), extended care services that are not post-hospital extended care services;"],[1,"(3) in the case of individuals not enrolled in part B, home health services, and in the case of individuals so enrolled, post-institutional home health services furnished during a home health spell of illness for up to 100 visits during such spell of illness;"],[1,"(4) in lieu of certain other benefits, hospice care with respect to the individual during up to two periods of 90 days each and an unlimited number of subsequent periods of 60 days each with respect to which the individual makes an election under subsection (d)(1); and"],[1,"(5) for individuals who are terminally ill, have not made an election under subsection (d)(1), and have not previously received services under this paragraph, services that are furnished by a physician (as defined in section 1395x(r)(1) of this title) who is either the medical director or an employee of a hospice program and that—"],[2,"(A) consist of—"],[3,"(i) an evaluation of the individual's need for pain and symptom management, including the individual's need for hospice care; and"],[3,"(ii) counseling the individual with respect to hospice care and other care options; and"],[2,"(B) may include advising the individual regarding advanced care planning."],[0,"(b) Services not covered"],[0,"Payment under this part for services furnished an individual during a spell of illness may not (subject to subsection (c)) be made for—"],[1,"(1) inpatient hospital services furnished to him during such spell after such services have been furnished to him for 150 days during such spell minus 1 day for each day of inpatient hospital services in excess of 90 received during any preceding spell of illness (if such individual was entitled to have payment for such services made under this part unless he specifies in accordance with regulations of the Secretary that he does not desire to have such payment made);"],[1,"(2) post-hospital extended care services furnished to him during such spell after such services have been furnished to him for 100 days during such spell; or"],[1,"(3) inpatient psychiatric hospital services furnished to him after such services have been furnished to him for a total of 190 days during his lifetime."],[0,"Payment under this part for post-institutional home health services furnished an individual during a home health spell of illness may not be made for such services beginning after such services have been furnished for a total of 100 visits during such spell."],[0,"(c) Inpatients of psychiatric hospitals"],[0,"If an individual is an inpatient of a psychiatric hospital on the first day of the first month for which he is entitled to benefits under this part, the days on which he was an inpatient of such a hospital in the 150-day period immediately before such first day shall be included in determining the number of days limit under subsection (b)(1) insofar as such limit applies to (1) inpatient psychiatric hospital services, or (2) inpatient hospital services for an individual who is an inpatient primarily for the diagnosis or treatment of mental illness (but shall not be included in determining such number of days limit insofar as it applies to other inpatient hospital services or in determining the 190-day limit under subsection (b)(3))."],[0,"(d) Hospice care; election; waiver of rights; revocation; change of election"],[0,"(1) Payment under this part may be made for hospice care provided with respect to an individual only during two periods of 90 days each and an unlimited number of subsequent periods of 60 days each during the individual's lifetime and only, with respect to each such period, if the individual makes an election under this paragraph to receive hospice care under this part provided by, or under arrangements made by, a particular hospice program instead of certain other benefits under this subchapter."],[0,"(2)(A) Except as provided in subparagraphs (B) and (C) and except in such exceptional and unusual circumstances as the Secretary may provide, if an individual makes such an election for a period with respect to a particular hospice program, the individual shall be deemed to have waived all rights to have payment made under this subchapter with respect to—"],[1,"(i) hospice care provided by another hospice program (other than under arrangements made by the particular hospice program) during the period, and"],[1,"(ii) services furnished during the period that are determined (in accordance with guidelines of the Secretary) to be—"],[2,"(I) related to the treatment of the individual's condition with respect to which a diagnosis of terminal illness has been made or"],[2,"(II) equivalent to (or duplicative of) hospice care;"],[0,"except that clause (ii) shall not apply to physicians' services furnished by the individual's attending physician (if not an employee of the hospice program) or to services provided by (or under arrangements made by) the hospice program."],[0,"(B) After an individual makes such an election with respect to a 90-day period or a subsequent 60-day period, the individual may revoke the election during the period, in which case—"],[1,"(i) the revocation shall act as a waiver of the right to have payment made under this part for any hospice care benefits for the remaining time in such period and (for purposes of subsection (a)(4) and subparagraph (A)) the individual shall be deemed to have been provided such benefits during such entire period, and"],[1,"(ii) the individual may at any time after the revocation execute a new election for a subsequent period, if the individual otherwise is entitled to hospice care benefits with respect to such a period."],[0,"(C) An individual may, once in each such period, change the hospice program with respect to which the election is made and such change shall not be considered a revocation of an election under subparagraph (B)."],[0,"(D) For purposes of this subchapter, an individual's election with respect to a hospice program shall no longer be considered to be in effect with respect to that hospice program after the date the individual's revocation or change of election with respect to that election takes effect."],[0,"(e) Services taken into account"],[0,"For purposes of subsections (b) and (c), inpatient hospital services, inpatient psychiatric hospital services, and post-hospital extended care services shall be taken into account only if payment is or would be, except for this section or the failure to comply with the request and certification requirements of or under section 1395f(a) of this title, made with respect to such services under this part."],[0,"(f) Coverage of extended care services without regard to three-day prior hospitalization requirement"],[0,"(1) The Secretary shall provide for coverage, under clause (B) of subsection (a)(2), of extended care services which are not post-hospital extended care services at such time and for so long as the Secretary determines, and under such terms and conditions (described in paragraph (2)) as the Secretary finds appropriate, that the inclusion of such services will not result in any increase in the total of payments made under this subchapter and will not alter the acute care nature of the benefit described in subsection (a)(2)."],[0,"(2) The Secretary may provide—"],[1,"(A) for such limitations on the scope and extent of services described in subsection (a)(2)(B) and on the categories of individuals who may be eligible to receive such services, and"],[1,"(B) notwithstanding sections 1395f, 1395x(v), and 1395ww of this title, for such restrictions and alternatives on the amounts and methods of payment for services described in such subsection,"],[0,"as may be necessary to carry out paragraph (1)."],[0,"(g) \"Spell of illness\" defined"],[0,"For definitions of \"spell of illness\", and for definitions of other terms used in this part, see section 1395x of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395d. Scope of benefits","tname":"The Public Health and Welfare","by":{"0":"30, 30, 30","1":"passim","2":"9, 2, 3, 5"}},{"t":"usc","label":"42 U.S.C. § 1395f","url":"https://www.law.cornell.edu/uscode/text/42/1395f","subs":["(b)(1)(1982)"],"by":{"0":"30, 2"}},{"t":"usc","label":"42 U.S.C. § 1395l","url":"https://www.law.cornell.edu/uscode/text/42/1395l","subs":["(a)(8)(B)(i)","(t)","(t)(1)(B)(ii)"],"stext":{"head":"§1395l. Payment of benefits","paras":[[0,"(a) Amounts"],[0,"Except as provided in section 1395mm of this title, and subject to the succeeding provisions of this section, there shall be paid from the Federal Supplementary Medical Insurance Trust Fund, in the case of each individual who is covered under the insurance program established by this part and incurs expenses for services with respect to which benefits are payable under this part, amounts equal to—"],[1,"(1) in the case of services described in section 1395k(a)(1) of this title—80 percent of the reasonable charges for the services; except that (A) an organization which provides medical and other health services (or arranges for their availability) on a prepayment basis (and either is sponsored by a union or employer, or does not provide, or arrange for the provision of, any inpatient hospital services) may elect to be paid 80 percent of the reasonable cost of services for which payment may be made under this part on behalf of individuals enrolled in such organization in lieu of 80 percent of the reasonable charges for such services if the organization undertakes to charge such individuals no more than 20 percent of such reasonable cost plus any amounts payable by them as a result of subsection (b), (B) with respect to items and services described in section 1395x(s)(10)(A) of this title, the amounts paid shall be 100 percent of the reasonable charges for such items and services, (C) with respect to expenses incurred for those physicians' services for which payment may be made under this part that are described in section 1395y(a)(4) of this title, the amounts paid shall be subject to such limitations as may be prescribed by regulations, (D) with respect to clinical diagnostic laboratory tests for which payment is made under this part (i)(I) on the basis of a fee schedule under subsection (h)(1) (for tests furnished before January 1, 2017) or section 1395m(d)(1) of this title, the amount paid shall be equal to 80 percent (or 100 percent, in the case of such tests for which payment is made on an assignment-related basis) of the lesser of the amount determined under such fee schedule, the limitation amount for that test determined under subsection (h)(4)(B), or the amount of the charges billed for the tests, or (II) under section 1395m–1 of this title (for tests furnished on or after January 1, 2017), the amount paid shall be equal to 80 percent (or 100 percent, in the case of such tests for which payment is made on an assignment-related basis) of the lesser of the amount determined under such section or the amount of the charges billed for the tests, or (ii) for tests furnished before January 1, 2017, on the basis of a negotiated rate established under subsection (h)(6), the amount paid shall be equal to 100 percent of such negotiated rate,,1 (E) with respect to services furnished to individuals who have been determined to have end stage renal disease, the amounts paid shall be determined subject to the provisions of section 1395rr of this title, (F) with respect to clinical social worker services under section 1395x(s)(2)(N) of this title, the amounts paid shall be 80 percent of the lesser of (i) the actual charge for the services or (ii) 75 percent of the amount determined for payment of a psychologist under clause (L), (G) with respect to facility services furnished in connection with a surgical procedure specified pursuant to subsection (i)(1)(A) and furnished to an individual in an ambulatory surgical center described in such subsection, for services furnished beginning with the implementation date of a revised payment system for such services in such facilities specified in subsection (i)(2)(D), the amounts paid, subject to subsection (i)(9), shall be 80 percent of the lesser of the actual charge for the services or the amount determined by the Secretary under such revised payment system, (H) with respect to services of a certified registered nurse anesthetist under section 1395x(s)(11) of this title, the amounts paid shall be 80 percent of the least of the actual charge, the prevailing charge that would be recognized (or, for services furnished on or after January 1, 1992, the fee schedule amount provided under section 1395w–4 of this title) if the services had been performed by an anesthesiologist, or the fee schedule for such services established by the Secretary in accordance with subsection (l), (I) with respect to covered items (described in section 1395m(a)(13) of this title), the amounts paid shall be the amounts described in section 1395m(a)(1) of this title, and 2 (J) with respect to expenses incurred for radiologist services (as defined in section 1395m(b)(6) of this title), subject to section 1395w–4 of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount provided under the fee schedule established under section 1395m(b) of this title, (K) with respect to certified nurse-midwife services under section 1395x(s)(2)(L) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary for the purposes of this subparagraph (but in no event shall such fee schedule exceed 65 percent of the prevailing charge that would be allowed for the same service performed by a physician, or, for services furnished on or after January 1, 1992, 65 percent (or 100 percent for services furnished on or after January 1, 2011) of the fee schedule amount provided under section 1395w–4 of this title for the same service performed by a physician), (L) with respect to qualified psychologist services under section 1395x(s)(2)(M) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary for the purposes of this subparagraph, (M) with respect to prosthetic devices and orthotics and prosthetics (as defined in section 1395m(h)(4) of this title), the amounts paid shall be the amounts described in section 1395m(h)(1) of this title, (N) with respect to expenses incurred for physicians' services (as defined in section 1395w–4(j)(3) of this title) other than personalized prevention plan services (as defined in section 1395x(hhh)(1) of this title), the amounts paid shall be 80 percent of the payment basis determined under section 1395w–4(a)(1) of this title, (O) with respect to services described in section 1395x(s)(2)(K) of this title (relating to services furnished by physician assistants, nurse practitioners, or clinic nurse specialists), the amounts paid shall be equal to 80 percent of (i) the lesser of the actual charge or 85 percent of the fee schedule amount provided under section 1395w–4 of this title, or (ii) in the case of services as an assistant at surgery, the lesser of the actual charge or 85 percent of the amount that would otherwise be recognized if performed by a physician who is serving as an assistant at surgery, (P) with respect to surgical dressings, the amounts paid shall be the amounts determined under section 1395m(i) of this title, (Q) with respect to items or services for which fee schedules are established pursuant to section 1395u(s) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the fee schedule established in such section, (R) with respect to ambulance services, (i) the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary under section 1395m(l) of this title and (ii) with respect to ambulance services described in section 1395m(l)(8) of this title, the amounts paid shall be the amounts determined under section 1395m(g) of this title for outpatient critical access hospital services, (S)(i) except as provided in clause (ii), subject to subparagraph (EE), with respect to drugs and biologicals (including intravenous immune globulin (as defined in section 1395x(zz) of this title)) not paid on a cost or prospective payment basis as otherwise provided in this part (other than items and services described in subparagraph (B)), the amounts paid shall be 80 percent of the lesser of the actual charge or the payment amount established in section 1395u(o) of this title (or, if applicable, under section 1395w–3, 1395w–3a, or 1395w–3b of this title), and (ii) with respect to insulin furnished on or after July 1, 2023, through an item of durable medical equipment covered under section 1395x(n) of this title, the amounts paid shall be, subject to the fourth sentence of this subsection, 80 percent of the payment amount established under section 1395w–3a of this title (or section 1395w–3b of this title, if applicable) for such insulin, (T) with respect to medical nutrition therapy services (as defined in section 1395x(vv) of this title), the amount paid shall be 80 percent (or 100 percent if such services are recommended with a grade of A or B by the United States Preventive Services Task Force for any indication or population and are appropriate for the individual) of the lesser of the actual charge for the services or 85 percent of the amount determined under the fee schedule established under section 1395w–4(b) of this title for the same services if furnished by a physician, (U) with respect to facility fees described in section 1395m(m)(2)(B) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the amounts specified in such section, (V) notwithstanding subparagraphs (I) (relating to durable medical equipment), (M) (relating to prosthetic devices and orthotics and prosthetics), and (Q) (relating to 1395u(s) items), with respect to competitively priced items and services (described in section 1395w–3(a)(2) of this title) that are furnished in a competitive area, the amounts paid shall be the amounts described in section 1395w–3(b)(5) of this title, (W) with respect to additional preventive services (as defined in section 1395x(ddd)(1) of this title), the amount paid shall be (i) in the case of such services which are clinical diagnostic laboratory tests, the amount determined under subparagraph (D) (if such subparagraph were applied, by substituting \"100 percent\" for \"80 percent\"), and (ii) in the case of all other such services, 100 percent of the lesser of the actual charge for the service or the amount determined under a fee schedule established by the Secretary for purposes of this subparagraph, (X) with respect to personalized prevention plan services (as defined in section 1395x(hhh)(1) of this title), the amount paid shall be 100 percent of the lesser of the actual charge for the services or the amount determined under the payment basis determined under section 1395w–4 of this title, (Y) subject to subsection (dd), with respect to preventive services described in subparagraphs (A) and (B) of section 1395x(ddd)(3) of this title that are appropriate for the individual and, in the case of such services described in subparagraph (A), are recommended with a grade of A or B by the United States Preventive Services Task Force for any indication or population, the amount paid shall be 100 percent of (i) except as provided in clause (ii), the lesser of the actual charge for the services or the amount determined under the fee schedule that applies to such services under this part, and (ii) in the case of such services that are covered OPD services (as defined in subsection (t)(1)(B)), the amount determined under subsection (t), (Z) with respect to Federally qualified health center services for which payment is made under section 1395m(o) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the amount determined under such section, (AA) with respect to an applicable disposable device (as defined in paragraph (2) of section 1395m(s) of this title) furnished to an individual pursuant to paragraph (1) of such section, the amount paid shall be equal to 80 percent of the lesser of the actual charge or the amount determined under paragraph (3) of such section, (BB) with respect to home infusion therapy, the amount paid shall be an amount equal to 80 percent of the lesser of the actual charge for the services or the amount determined under section 1395m(u) of this title, (CC) with respect to opioid use disorder treatment services furnished during an episode of care, the amount paid shall be equal to the amount payable under section 1395m(w) of this title less any copayment required as specified by the Secretary, (DD) with respect to a specified COVID–19 testing-related service described in paragraph (1) of subsection (cc) for which payment may be made under a specified outpatient payment provision described in paragraph (2) of such subsection, the amounts paid shall be 100 percent of the payment amount otherwise recognized under such respective specified outpatient payment provision for such service, (EE) with respect to a part B rebatable drug (as defined in paragraph (2) of section 1395w–3a(i) of this title) furnished on or after April 1, 2023, for which the payment amount for a calendar quarter under paragraph (3)(A)(ii)(I) of such section (or, in the case of a part B rebatable drug that is a selected drug (as defined in section 1320f–1(c) of this title for which, the payment amount described in section 1395w–3a(b)(1)(B) of this title) for such drug for such quarter exceeds the inflation-adjusted payment under paragraph (3)(A)(ii)(II) of such section for such quarter, the amounts paid shall be equal to the percent of the payment amount under paragraph (3)(A)(ii)(I) of such section or section 1395w–3a(b)(1)(B) of this title, as applicable, that equals the difference between (i) 100 percent, and (ii) the percent applied under section 1395w–3a(i)(5)(B) of this title 3 (FF) with respect to marriage and family therapist services and mental health counselor services under section 1395x(s)(2)(II) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or 75 percent of the amount determined for payment of a psychologist under subparagraph (L), (GG) with respect to lymphedema compression treatment items (as defined in section 1395x(mmm) of this title), the amount paid shall be equal to 80 percent of the lesser of the actual charge or the amount determined under the payment basis determined under section 1395m(z) of this title, and (HH) with respect to items and services related to the administration of intravenous immune globulin furnished on or after January 1, 2024, as described in section 1395x(zz) of this title, the amounts paid shall be the lesser of the 80 percent of the actual charge or the payment amount established under section 1395u(o)(8) of this title;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395l?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1395l. Payment of benefits","tname":"The Public Health and Welfare","by":{"0":"3, 3, 3","1":"41","2":"5, 6, 5, 6"}},{"t":"usc","label":"42 U.S.C. § 1395o","url":"https://www.law.cornell.edu/uscode/text/42/1395o","subs":["(a)(1)"],"stext":{"head":"§1395o. Eligible individuals","paras":[[0,"(a) In general"],[0,"Every individual who—"],[1,"(1) is entitled to hospital insurance benefits under part A, or"],[1,"(2) has attained age 65 and is a resident of the United States, and is either (A) a citizen or (B) an alien lawfully admitted for permanent residence who has resided in the United States continuously during the 5 years immediately preceding the month in which he applies for enrollment under this part,"],[0,"is eligible to enroll in the insurance program established by this part."],[0,"(b) Individuals eligible for immunosuppressive drug coverage"],[0,"(1) In general"],[1,"Except as provided under paragraph (2), every individual whose entitlement to insurance benefits under part A ends (whether before, on, or after January 1, 2023) by reason of section 426–1(b)(2) of this title is eligible to enroll or to be deemed to have enrolled in the medical insurance program established by this part solely for purposes of coverage of immunosuppressive drugs in accordance with section 1395p(n) of this title."],[0,"(2) Exception if other coverage is available"],[0,"(A) In general"],[2,"An individual described in paragraph (1) shall not be eligible for enrollment in the program for purposes of coverage described in such paragraph with respect to any period in which the individual, as determined in accordance with subparagraph (B)—"],[3,"(i) is enrolled in a group health plan or group or individual health insurance coverage, as such terms are defined in section 300gg–91 of this title;"],[3,"(ii) is enrolled for coverage under the TRICARE for Life program under section 1086(d) of title 10;"],[3,"(iii) is enrolled under a State plan (or waiver of such plan) under subchapter XIX and is eligible to receive benefits for immunosuppressive drugs described in this subsection under such plan (or such waiver);"],[3,"(iv) is enrolled under a State child health plan (or waiver of such plan) under subchapter XXI and is eligible to receive benefits for such drugs under such plan (or such waiver); or"],[3,"(v)(I) is enrolled in the patient enrollment system of the Department of Veterans Affairs established and operated under section 1705 of title 38;"],[3,"(II) is not required to enroll under section 1705 of such title to receive immunosuppressive drugs described in this subsection; or"],[3,"(III) is otherwise eligible under a provision of title 38, other than section 1710 of such title to receive immunosuppressive drugs described in this subsection."],[0,"(B) Eligibility determinations"],[0,"(i) In general"],[3,"The Secretary, in coordination with the Commissioner of Social Security, shall establish a process for determining whether an individual described in paragraph (1) who is to be enrolled or deemed to be enrolled in the medical insurance program described in such paragraph meets the requirements for such enrollment under this subsection, including the requirement that the individual not be enrolled in other coverage as described in subparagraph (A)."],[0,"(ii) Attestation regarding other coverage"],[3,"The process established under clause (i) shall include, at a minimum, a requirement that—"],[4,"(I) the individual provide to the Commissioner an attestation that the individual is not enrolled and does not expect to enroll in such other coverage; and"],[4,"(II) the individual notify the Commissioner within 60 days of enrollment in such other coverage."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395o?type=usc&year=mostrecent&link-type=html"},"head":"§1395o. Eligible individuals","tname":"The Public Health and Welfare","by":{"0":"3","1":"42, 43","2":"6"}},{"t":"usc","label":"42 U.S.C. § 1395w-21","url":"https://www.law.cornell.edu/uscode/text/42/1395w-21","subs":["(a)(3)"],"stext":{"head":"§1395w–21. Eligibility, election, and enrollment","paras":[[0,"(a) Choice of medicare benefits through Medicare+Choice plans"],[0,"(1) In general"],[1,"Subject to the provisions of this section, each Medicare+Choice eligible individual (as defined in paragraph (3)) is entitled to elect to receive benefits (other than qualified prescription drug benefits) under this subchapter—"],[2,"(A) through the original medicare fee-for-service program under parts A and B, or"],[2,"(B) through enrollment in a Medicare+Choice plan under this part,"],[1,"and may elect qualified prescription drug coverage in accordance with section 1395w–101 of this title."],[0,"(2) Types of Medicare+Choice plans that may be available"],[1,"A Medicare+Choice plan may be any of the following types of plans of health insurance:"],[0,"(A) Coordinated care plans (including regional plans)"],[0,"(i) In general"],[3,"Coordinated care plans which provide health care services, including but not limited to health maintenance organization plans (with or without point of service options), plans offered by provider-sponsored organizations (as defined in section 1395w–25(d) of this title), and regional or local preferred provider organization plans (including MA regional plans)."],[0,"(ii) Specialized MA plans for special needs individuals"],[3,"Specialized MA plans for special needs individuals (as defined in section 1395w–28(b)(6) of this title) may be any type of coordinated care plan."],[0,"(B) Combination of MSA plan and contributions to Medicare+Choice MSA"],[2,"An MSA plan, as defined in section 1395w–28(b)(3) of this title, and a contribution into a Medicare+Choice medical savings account (MSA)."],[0,"(C) Private fee-for-service plans"],[2,"A Medicare+Choice private fee-for-service plan, as defined in section 1395w–28(b)(2) of this title."],[0,"(3) Medicare+Choice eligible individual"],[1,"In this subchapter, the term \"Medicare+Choice eligible individual\" means an individual who is entitled to benefits under part A and enrolled under part B."],[0,"(b) Special rules"],[0,"(1) Residence requirement"],[0,"(A) In general"],[2,"Except as the Secretary may otherwise provide and except as provided in subparagraph (C), an individual is eligible to elect a Medicare+Choice plan offered by a Medicare+Choice organization only if the plan serves the geographic area in which the individual resides."],[0,"(B) Continuation of enrollment permitted"],[2,"Pursuant to rules specified by the Secretary, the Secretary shall provide that an MA local plan may offer to all individuals residing in a geographic area the option to continue enrollment in the plan, notwithstanding that the individual no longer resides in the service area of the plan, so long as the plan provides that individuals exercising this option have, as part of the benefits under the original medicare fee-for-service program option, reasonable access within that geographic area to the full range of basic benefits, subject to reasonable cost sharing liability in obtaining such benefits."],[0,"(C) Continuation of enrollment permitted where service changed"],[2,"Notwithstanding subparagraph (A) and in addition to subparagraph (B), if a Medicare+Choice organization eliminates from its service area a Medicare+Choice payment area that was previously within its service area, the organization may elect to offer individuals residing in all or portions of the affected area who would otherwise be ineligible to continue enrollment the option to continue enrollment in an MA local plan it offers so long as—"],[3,"(i) the enrollee agrees to receive the full range of basic benefits (excluding emergency and urgently needed care) exclusively at facilities designated by the organization within the plan service area; and"],[3,"(ii) there is no other Medicare+Choice plan offered in the area in which the enrollee resides at the time of the organization's election."],[0,"(2) Special rule for certain individuals covered under FEHBP or eligible for veterans or military health benefits"],[0,"(A) FEHBP"],[2,"An individual who is enrolled in a health benefit plan under chapter 89 of title 5 is not eligible to enroll in an MSA plan until such time as the Director of the Office of Management and Budget certifies to the Secretary that the Office of Personnel Management has adopted policies which will ensure that the enrollment of such individuals in such plans will not result in increased expenditures for the Federal Government for health benefit plans under such chapter."],[0,"(B) VA and DOD"],[2,"The Secretary may apply rules similar to the rules described in subparagraph (A) in the case of individuals who are eligible for health care benefits under chapter 55 of title 10 or under chapter 17 of title 38."],[0,"(3) Limitation on eligibility of qualified medicare beneficiaries and other medicaid beneficiaries to enroll in an MSA plan"],[1,"An individual who is a qualified medicare beneficiary (as defined in section 1396d(p)(1) of this title), a qualified disabled and working individual (described in section 1396d(s) of this title), an individual described in section 1396a(a)(10)(E)(iii) of this title, or otherwise entitled to medicare cost-sharing under a State plan under subchapter XIX is not eligible to enroll in an MSA plan."],[0,"(4) Coverage under MSA plans"],[0,"(A) In general"],[2,"Under rules established by the Secretary, an individual is not eligible to enroll (or continue enrollment) in an MSA plan for a year unless the individual provides assurances satisfactory to the Secretary that the individual will reside in the United States for at least 183 days during the year."],[0,"(B) Evaluation"],[2,"The Secretary shall regularly evaluate the impact of permitting enrollment in MSA plans under this part on selection (including adverse selection), use of preventive care, access to care, and the financial status of the Trust Funds under this subchapter."],[0,"(C) Reports"],[2,"The Secretary shall submit to Congress periodic reports on the numbers of individuals enrolled in such plans and on the evaluation being conducted under subparagraph (B)."],[0,"(c) Process for exercising choice"],[0,"(1) In general"],[1,"The Secretary shall establish a process through which elections described in subsection (a) are made and changed, including the form and manner in which such elections are made and changed. Subject to paragraph (4), such elections shall be made or changed only during coverage election periods specified under subsection (e) and shall become effective as provided in subsection (f)."],[0,"(2) Coordination through Medicare+Choice organizations"],[0,"(A) Enrollment"],[2,"Such process shall permit an individual who wishes to elect a Medicare+Choice plan offered by a Medicare+Choice organization to make such election through the filing of an appropriate election form with the organization."],[0,"(B) Disenrollment"],[2,"Such process shall permit an individual, who has elected a Medicare+Choice plan offered by a Medicare+Choice organization and who wishes to terminate such election, to terminate such election through the filing of an appropriate election form with the organization."],[0,"(3) Default"],[0,"(A) Initial election"],[0,"(i) In general"],[3,"Subject to clause (ii), an individual who fails to make an election during an initial election period under subsection (e)(1) is deemed to have chosen the original medicare fee-for-service program option."],[0,"(ii) Seamless continuation of coverage"],[3,"The Secretary may establish procedures under which an individual who is enrolled in a health plan (other than Medicare+Choice plan) offered by a Medicare+Choice organization at the time of the initial election period and who fails to elect to receive coverage other than through the organization is deemed to have elected the Medicare+Choice plan offered by the organization (or, if the organization offers more than one such plan, such plan or plans as the Secretary identifies under such procedures)."],[0,"(B) Continuing periods"],[2,"An individual who has made (or is deemed to have made) an election under this section is considered to have continued to make such election until such time as—"],[3,"(i) the individual changes the election under this section, or"],[3,"(ii) the Medicare+Choice plan with respect to which such election is in effect is discontinued or, subject to subsection (b)(1)(B), no longer serves the area in which the individual resides."],[0,"(4) Deemed enrollment relating to converted reasonable cost reimbursement contracts"],[0,"(A) In general"],[2,"On the first day of the annual, coordinated election period under subsection (e)(3) for plan years beginning on or after January 1, 2017, an MA eligible individual described in clause (i) or (ii) of subparagraph (B) is deemed, unless the individual elects otherwise, to have elected to receive benefits under this subchapter through an applicable MA plan (and shall be enrolled in such plan) beginning with such plan year, if—"],[3,"(i) the individual is enrolled in a reasonable cost reimbursement contract under section 1395mm(h) of this title in the previous plan year;"],[3,"(ii) such reasonable cost reimbursement contract was extended or renewed for the last reasonable cost reimbursement contract year of the contract (as described in subclause (I) of section 1395mm(h)(5)(C)(iv) of this title) pursuant to such section;"],[3,"(iii) the eligible organization that is offering such reasonable cost reimbursement contract provided the notice described in subclause (III) of such section that the contract was to be converted;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395w-21?type=usc&year=mostrecent&link-type=html"},"head":"§1395w–21. Eligibility, election, and enrollment","tname":"The Public Health and Welfare","by":{"0":"3","1":"42, 43","2":"6, 6"}},{"t":"usc","label":"42 U.S.C. § 1395w-101","url":"https://www.law.cornell.edu/uscode/text/42/1395w-101","subs":["(a)(3)(A)"],"stext":{"head":"§1395w–101. Eligibility, enrollment, and information","paras":[[0,"(a) Provision of qualified prescription drug coverage through enrollment in plans"],[0,"(1) In general"],[1,"Subject to the succeeding provisions of this part, each part D eligible individual (as defined in paragraph (3)(A)) is entitled to obtain qualified prescription drug coverage (described in section 1395w–102(a) of this title) as follows:"],[0,"(A) Fee-for-service enrollees may receive coverage through a prescription drug plan"],[2,"A part D eligible individual who is not enrolled in an MA plan may obtain qualified prescription drug coverage through enrollment in a prescription drug plan (as defined in section 1395w–151(a)(14) of this title)."],[0,"(B) Medicare Advantage enrollees"],[0,"(i) Enrollees in a plan providing qualified prescription drug coverage receive coverage through the plan"],[3,"A part D eligible individual who is enrolled in an MA–PD plan obtains such coverage through such plan."],[0,"(ii) Limitation on enrollment of MA plan enrollees in prescription drug plans"],[3,"Except as provided in clauses (iii) and (iv), a part D eligible individual who is enrolled in an MA plan may not enroll in a prescription drug plan under this part."],[0,"(iii) Private fee-for-service enrollees in MA plans not providing qualified prescription drug coverage permitted to enroll in a prescription drug plan"],[3,"A part D eligible individual who is enrolled in an MA private fee-for-service plan (as defined in section 1395w–28(b)(2) of this title) that does not provide qualified prescription drug coverage may obtain qualified prescription drug coverage through enrollment in a prescription drug plan."],[0,"(iv) Enrollees in MSA plans permitted to enroll in a prescription drug plan"],[3,"A part D eligible individual who is enrolled in an MSA plan (as defined in section 1395w–28(b)(3) of this title) may obtain qualified prescription drug coverage through enrollment in a prescription drug plan."],[0,"(2) Coverage first effective January 1, 2006"],[1,"Coverage under prescription drug plans and MA–PD plans shall first be effective on January 1, 2006."],[0,"(3) Definitions"],[1,"For purposes of this part:"],[0,"(A) Part D eligible individual"],[2,"The term \"part D eligible individual\" means an individual who is entitled to benefits under part A or enrolled under part B (but not including an individual enrolled solely for coverage of immunosuppressive drugs under section 1395o(b) of this title)."],[0,"(B) MA plan"],[2,"The term \"MA plan\" has the meaning given such term in section 1395w–28(b)(1) of this title."],[0,"(C) MA–PD plan"],[2,"The term \"MA–PD plan\" means an MA plan that provides qualified prescription drug coverage."],[0,"(b) Enrollment process for prescription drug plans"],[0,"(1) Establishment of process"],[0,"(A) In general"],[2,"The Secretary shall establish a process for the enrollment, disenrollment, termination, and change of enrollment of part D eligible individuals in prescription drug plans consistent with this subsection."],[0,"(B) Application of MA rules"],[2,"In establishing such process, the Secretary shall use rules similar to (and coordinated with) the rules for enrollment, disenrollment, termination, and change of enrollment with an MA–PD plan under the following provisions of section 1395w–21 of this title:"],[0,"(i) Residence requirements"],[3,"Section 1395w–21(b)(1)(A) of this title, relating to residence requirements."],[0,"(ii) Exercise of choice"],[3,"Section 1395w–21(c) of this title (other than paragraph (3)(A) and paragraph (4) of such section), relating to exercise of choice."],[0,"(iii) Coverage election periods"],[3,"Subject to paragraphs (2) and (3) of this subsection, section 1395w–21(e) of this title (other than subparagraphs (B), (C), (E), and (F) of paragraph (2) and the second sentence of paragraph (4) of such section), relating to coverage election periods, including initial periods, annual coordinated election periods, special election periods, and election periods for exceptional circumstances."],[0,"(iv) Coverage periods"],[3,"Section 1395w–21(f) of this title, relating to effectiveness of elections and changes of elections."],[0,"(v) Guaranteed issue and renewal"],[3,"Section 1395w–21(g) of this title (other than paragraph (2) of such section and clause (i) and the second sentence of clause (ii) of paragraph (3)(C) of such section), relating to guaranteed issue and renewal."],[0,"(vi) Marketing material and application forms"],[3,"Section 1395w–21(h) of this title, relating to approval of marketing material and application forms."],[2,"In applying clauses (ii), (iv), and (v) of this subparagraph, any reference to section 1395w–21(e) of this title shall be treated as a reference to such section as applied pursuant to clause (iii) of this subparagraph."],[0,"(C) Special rule"],[2,"The process established under subparagraph (A) shall include, except as provided in subparagraph (D), in the case of a part D eligible individual who is a full-benefit dual eligible individual (as defined in section 1396u–5(c)(6) of this title) who has failed to enroll in a prescription drug plan or an MA–PD plan, for the enrollment in a prescription drug plan that has a monthly beneficiary premium that does not exceed the premium assistance available under section 1395w–114(a)(1)(A) of this title).1 If there is more than one such plan available, the Secretary shall enroll such an individual on a random basis among all such plans in the PDP region. Nothing in the previous sentence shall prevent such an individual from declining or changing such enrollment."],[0,"(D) Special rule for plans that waive de minimis premiums"],[2,"The process established under subparagraph (A) may include, in the case of a part D eligible individual who is a subsidy eligible individual (as defined in section 1395w–114(a)(3) of this title) who has failed to enroll in a prescription drug plan or an MA–PD plan, for the enrollment in a prescription drug plan or MA–PD plan that has waived the monthly beneficiary premium for such subsidy eligible individual under section 1395w–114(a)(5) of this title. If there is more than one such plan available, the Secretary shall enroll such an individual under the preceding sentence on a random basis among all such plans in the PDP region. Nothing in the previous sentence shall prevent such an individual from declining or changing such enrollment."],[0,"(2) Initial enrollment period"],[0,"(A) Program initiation"],[2,"In the case of an individual who is a part D eligible individual as of November 15, 2005, there shall be an initial enrollment period that shall be the same as the annual, coordinated open election period described in section 1395w–21(e)(3)(B)(iii) of this title, as applied under paragraph (1)(B)(iii)."],[0,"(B) Continuing periods"],[2,"In the case of an individual who becomes a part D eligible individual after November 15, 2005, there shall be an initial enrollment period which is the period under section 1395w–21(e)(1) of this title, as applied under paragraph (1)(B)(iii) of this section,2 as if \"entitled to benefits under part A or enrolled under part B\" were substituted for \"entitled to benefits under part A and enrolled under part B\", but in no case shall such period end before the period described in subparagraph (A)."],[0,"(3) Additional special enrollment periods"],[1,"The Secretary shall establish special enrollment periods, including the following:"],[0,"(A) Involuntary loss of creditable prescription drug coverage"],[0,"(i) In general"],[3,"In the case of a part D eligible individual who involuntarily loses creditable prescription drug coverage (as defined in section 1395w–113(b)(4) of this title)."],[0,"(ii) Notice"],[3,"In establishing special enrollment periods under clause (i), the Secretary shall take into account when the part D eligible individuals are provided notice of the loss of creditable prescription drug coverage."],[0,"(iii) Failure to pay premium"],[3,"For purposes of clause (i), a loss of coverage shall be treated as voluntary if the coverage is terminated because of failure to pay a required beneficiary premium."],[0,"(iv) Reduction in coverage"],[3,"For purposes of clause (i), a reduction in coverage so that the coverage no longer meets the requirements under section 1395w–113(b)(5) of this title (relating to actuarial equivalence) shall be treated as an involuntary loss of coverage."],[0,"(B) Errors in enrollment"],[2,"In the case described in section 1395p(h) of this title (relating to errors in enrollment), in the same manner as such section applies to part B."],[0,"(C) Exceptional circumstances"],[2,"In the case of part D eligible individuals who meet such exceptional conditions (in addition to those conditions applied under paragraph (1)(B)(iii)) as the Secretary may provide."],[0,"(D) Medicaid coverage"],[2,"In the case of an individual (as determined by the Secretary, subject to such limits as the Secretary may establish for individuals identified pursuant to section 1395w–104(c)(5) of this title) who is a full-benefit dual eligible individual (as defined in section 1396u–5(c)(6) of this title)."],[0,"(E) Discontinuance of MA–PD election during first year of eligibility"],[2,"In the case of a part D eligible individual who discontinues enrollment in an MA–PD plan under the second sentence of section 1395w–21(e)(4) of this title at the time of the election of coverage under such sentence under the original medicare fee-for-service program."],[0,"(4) Information to facilitate enrollment"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395w-101?type=usc&year=mostrecent&link-type=html"},"head":"§1395w–101. Eligibility, enrollment, and information","tname":"The Public Health and Welfare","by":{"0":"3","1":"42, 43","2":"6, 6"}},{"t":"usc","label":"42 U.S.C. § 1395x","url":"https://www.law.cornell.edu/uscode/text/42/1395x","subs":["(a)","(v)(1)(A)(1982)"],"stext":{"head":"§1395x. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Spell of illness"],[0,"The term \"spell of illness\" with respect to any individual means a period of consecutive days—"],[1,"(1) beginning with the first day (not included in a previous spell of illness) (A) on which such individual is furnished inpatient hospital services, inpatient critical access hospital services or extended care services, and (B) which occurs in a month for which he is entitled to benefits under part A, and"],[1,"(2) ending with the close of the first period of 60 consecutive days thereafter on each of which he is neither an inpatient of a hospital or critical access hospital nor an inpatient of a facility described in section 1395i–3(a)(1) of this title or subsection (y)(1)."],[0,"(b) Inpatient hospital services"],[0,"The term \"inpatient hospital services\" means the following items and services furnished to an inpatient of a hospital and (except as provided in paragraph (3)) by the hospital—"],[1,"(1) bed and board;"],[1,"(2) such nursing services and other related services, such use of hospital facilities, and such medical social services as are ordinarily furnished by the hospital for the care and treatment of inpatients, and such drugs, biologicals, supplies, appliances, and equipment, for use in the hospital, as are ordinarily furnished by such hospital for the care and treatment of inpatients; and"],[1,"(3) such other diagnostic or therapeutic items or services, furnished by the hospital or by others under arrangements with them made by the hospital, as are ordinarily furnished to inpatients either by such hospital or by others under such arrangements;"],[0,"excluding, however—"],[1,"(4) medical or surgical services provided by a physician, resident, or intern, services described by subsection (s)(2)(K), certified nurse-midwife services, qualified psychologist services, and services of a certified registered nurse anesthetist; and"],[1,"(5) the services of a private-duty nurse or other private-duty attendant."],[0,"Paragraph (4) shall not apply to services provided in a hospital by—"],[1,"(6) an intern or a resident-in-training under a teaching program approved by the Council on Medical Education of the American Medical Association or, in the case of an osteopathic hospital, approved by the Committee on Hospitals of the Bureau of Professional Education of the American Osteopathic Association, or, in the case of services in a hospital or osteopathic hospital by an intern or resident-in-training in the field of dentistry, approved by the Council on Dental Education of the American Dental Association, or in the case of services in a hospital or osteopathic hospital by an intern or resident-in-training in the field of podiatry, approved by the Council on Podiatric Medical Education of the American Podiatric Medical Association; or"],[1,"(7) a physician where the hospital has a teaching program approved as specified in paragraph (6), if (A) the hospital elects to receive any payment due under this subchapter for reasonable costs of such services, and (B) all physicians in such hospital agree not to bill charges for professional services rendered in such hospital to individuals covered under the insurance program established by this subchapter."],[0,"(c) Inpatient psychiatric hospital services"],[0,"The term \"inpatient psychiatric hospital services\" means inpatient hospital services furnished to an inpatient of a psychiatric hospital."],[0,"(d) Supplier"],[0,"The term \"supplier\" means, unless the context otherwise requires, a physician or other practitioner, a facility, or other entity (other than a provider of services) that furnishes items or services under this subchapter."],[0,"(e) Hospital"],[0,"The term \"hospital\" (except for purposes of sections 1395f(d), 1395f(f), and 1395n(b) of this title, subsection (a)(2) of this section, paragraph (7) of this subsection, and subsection (i) of this section) means an institution which—"],[1,"(1) is primarily engaged in providing, by or under the supervision of physicians, to inpatients (A) diagnostic services and therapeutic services for medical diagnosis, treatment, and care of injured, disabled, or sick persons, or (B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons;"],[1,"(2) maintains clinical records on all patients;"],[1,"(3) has bylaws in effect with respect to its staff of physicians;"],[1,"(4) has a requirement that every patient with respect to whom payment may be made under this subchapter must be under the care of a physician, except that a patient receiving qualified psychologist services (as defined in subsection (ii)) may be under the care of a clinical psychologist with respect to such services to the extent permitted under State law;"],[1,"(5) provides 24-hour nursing service rendered or supervised by a registered professional nurse, and has a licensed practical nurse or registered professional nurse on duty at all times; except that until January 1, 1979, the Secretary is authorized to waive the requirement of this paragraph for any one-year period with respect to any institution, insofar as such requirement relates to the provision of twenty-four-hour nursing service rendered or supervised by a registered professional nurse (except that in any event a registered professional nurse must be present on the premises to render or supervise the nursing service provided, during at least the regular daytime shift), where immediately preceding such one-year period he finds that—"],[2,"(A) such institution is located in a rural area and the supply of hospital services in such area is not sufficient to meet the needs of individuals residing therein,"],[2,"(B) the failure of such institution to qualify as a hospital would seriously reduce the availability of such services to such individuals, and"],[2,"(C) such institution has made and continues to make a good faith effort to comply with this paragraph, but such compliance is impeded by the lack of qualified nursing personnel in such area;"],[1,"(6)(A) has in effect a hospital utilization review plan which meets the requirements of subsection (k) and (B) has in place a discharge planning process that meets the requirements of subsection (ee);"],[1,"(7) in the case of an institution in any State in which State or applicable local law provides for the licensing of hospitals, (A) is licensed pursuant to such law or (B) is approved, by the agency of such State or locality responsible for licensing hospitals, as meeting the standards established for such licensing;"],[1,"(8) has in effect an overall plan and budget that meets the requirements of subsection (z); and"],[1,"(9) meets such other requirements as the Secretary finds necessary in the interest of the health and safety of individuals who are furnished services in the institution."],[0,"For purposes of subsection (a)(2), such term includes any institution which meets the requirements of paragraph (1) of this subsection. For purposes of sections 1395f(d) and 1395n(b) of this title (including determination of whether an individual received inpatient hospital services or diagnostic services for purposes of such sections), section 1395f(f)(2) of this title, and subsection (i) of this section, such term includes any institution which (i) meets the requirements of paragraphs (5) and (7) of this subsection, (ii) is not primarily engaged in providing the services described in subsection (j)(1)(A) and (iii) is primarily engaged in providing, by or under the supervision of individuals referred to in paragraph (1) of subsection (r), to inpatients diagnostic services and therapeutic services for medical diagnosis, treatment, and care of injured, disabled, or sick persons, or rehabilitation services for the rehabilitation of injured, disabled, or sick persons. For purposes of section 1395f(f)(1) of this title, such term includes an institution which (i) is a hospital for purposes of sections 1395f(d), 1395f(f)(2), and 1395n(b) of this title and (ii) is accredited by a national accreditation body recognized by the Secretary under section 1395bb(a) of this title, or is accredited by or approved by a program of the country in which such institution is located if the Secretary finds the accreditation or comparable approval standards of such program to be essentially equivalent to those of such a national accreditation body..1 Notwithstanding the preceding provisions of this subsection, such term shall not, except for purposes of subsection (a)(2), include any institution which is primarily for the care and treatment of mental diseases unless it is a psychiatric hospital (as defined in subsection (f)). The term \"hospital\" also includes a religious nonmedical health care institution (as defined in subsection (ss)(1)), but only with respect to items and services ordinarily furnished by such institution to inpatients, and payment may be made with respect to services provided by or in such an institution only to such extent and under such conditions, limitations, and requirements (in addition to or in lieu of the conditions, limitations, and requirements otherwise applicable) as may be provided in regulations consistent with section 1395i–5 of this title. For provisions deeming certain requirements of this subsection to be met in the case of accredited institutions, see section 1395bb of this title. The term \"hospital\" also includes a facility of fifty beds or less which is located in an area determined by the Secretary to meet the definition relating to a rural area described in subparagraph (A) of paragraph (5) of this subsection and which meets the other requirements of this subsection, except that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395x?type=usc&year=mostrecent&link-type=html"},"head":"§1395x. Definitions","tname":"The Public Health and Welfare","by":{"0":"3, 3","2":"21"}},{"t":"usc","label":"42 U.S.C. § 1395y","url":"https://www.law.cornell.edu/uscode/text/42/1395y","subs":["(b)(2)(A)"],"by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 1395ww","url":"https://www.law.cornell.edu/uscode/text/42/1395ww","subs":["(d)(1)","(d)(5)","(d)(5)(C)(i)","(d)(5)(F)","(d)(5)(F)(i)","(d)(5)(F)(v)","(d)(5)(F)(vi)","(d)(5)(F)(vi)(I)","(d)(5)(F)(vi)(II)","(d)(5)(F)(vii)","(r)(1)","(h)(3)(C)"],"stext":{"head":"§1395ww. Payments to hospitals for inpatient hospital services","paras":[[0,"(a) Determination of costs for inpatient hospital services; limitations; exemptions; \"operating costs of inpatient hospital services\" defined"],[0,"(1)(A)(i) The Secretary, in determining the amount of the payments that may be made under this subchapter with respect to operating costs of inpatient hospital services (as defined in paragraph (4)) shall not recognize as reasonable (in the efficient delivery of health services) costs for the provision of such services by a hospital for a cost reporting period to the extent such costs exceed the applicable percentage (as determined under clause (ii)) of the average of such costs for all hospitals in the same grouping as such hospital for comparable time periods."],[0,"(ii) For purposes of clause (i), the applicable percentage for hospital cost reporting periods beginning—"],[1,"(I) on or after October 1, 1982, and before October 1, 1983, is 120 percent;"],[1,"(II) on or after October 1, 1983, and before October 1, 1984, is 115 percent; and"],[1,"(III) on or after October 1, 1984, is 110 percent."],[0,"(B)(i) For purposes of subparagraph (A) the Secretary shall establish case mix indexes for all short-term hospitals, and shall set limits for each hospital based upon the general mix of types of medical cases with respect to which such hospital provides services for which payment may be made under this subchapter."],[0,"(ii) The Secretary shall set such limits for a cost reporting period of a hospital—"],[1,"(I) by updating available data for a previous period to the immediate preceding cost reporting period by the estimated average rate of change of hospital costs industry-wide, and"],[1,"(II) by projecting for the cost reporting period by the applicable percentage increase (as defined in subsection (b)(3)(B))."],[0,"(C) The limitation established under subparagraph (A) for any hospital shall in no event be lower than the allowable operating costs of inpatient hospital services (as defined in paragraph (4)) recognized under this subchapter for such hospital for such hospital's last cost reporting period prior to the hospital's first cost reporting period for which this section is in effect."],[0,"(D) Subparagraph (A) shall not apply to cost reporting periods beginning on or after October 1, 1983."],[0,"(2) The Secretary shall provide for such exemptions from, and exceptions and adjustments to, the limitation established under paragraph (1)(A) as he deems appropriate, including those which he deems necessary to take into account—"],[1,"(A) the special needs of sole community hospitals, of new hospitals, of risk based health maintenance organizations, and of hospitals which provide atypical services or essential community services, and to take into account extraordinary circumstances beyond the hospital's control, medical and paramedical education costs, significantly fluctuating population in the service area of the hospital, and unusual labor costs,"],[1,"(B) the special needs of psychiatric hospitals and of public or other hospitals that serve a significantly disproportionate number of patients who have low income or are entitled to benefits under part A of this subchapter, and"],[1,"(C) a decrease in the inpatient hospital services that a hospital provides and that are customarily provided directly by similar hospitals which results in a significant distortion in the operating costs of inpatient hospital services."],[0,"(3) The limitation established under paragraph (1)(A) shall not apply with respect to any hospital which—"],[1,"(A) is located outside of a standard metropolitan statistical area, and"],[1,"(B)(i) has less than 50 beds, and"],[1,"(ii) was in operation and had less than 50 beds on September 3, 1982."],[0,"(4) For purposes of this section, the term \"operating costs of inpatient hospital services\" includes all routine operating costs, ancillary service operating costs, and special care unit operating costs with respect to inpatient hospital services as such costs are determined on an average per admission or per discharge basis (as determined by the Secretary), and includes the costs of all services for which payment may be made under this subchapter that are provided by the hospital (or by an entity wholly owned or operated by the hospital) to the patient during the 3 days (or, in the case of a hospital that is not a subsection (d) hospital, during the 1 day) immediately preceding the date of the patient's admission if such services are diagnostic services (including clinical diagnostic laboratory tests) or are other services related to the admission (as defined by the Secretary). Such term does not include costs of approved educational activities, a return on equity capital, other capital-related costs (as defined by the Secretary for periods before October 1, 1987), for cost reporting periods beginning on or after October 1, 2020, costs related to hematopoietic stem cell acquisition for the purpose of an allogeneic hematopoietic stem cell transplant (as described in subsection (d)(5)(M)), or costs with respect to administering blood clotting factors to individuals with hemophilia. In applying the first sentence of this paragraph, the term \"other services related to the admission\" includes all services that are not diagnostic services (other than ambulance and maintenance renal dialysis services) for which payment may be made under this subchapter that are provided by a hospital (or an entity wholly owned or operated by the hospital) to a patient—"],[1,"(A) on the date of the patient's inpatient admission; or"],[1,"(B) during the 3 days (or, in the case of a hospital that is not a subsection (d) hospital, during the 1 day) immediately preceding the date of such admission unless the hospital demonstrates (in a form and manner, and at a time, specified by the Secretary) that such services are not related (as determined by the Secretary) to such admission."],[0,"(b) Computation of payment; definitions; exemptions; adjustments"],[0,"(1) Notwithstanding section 1395f(b) of this title but subject to the provisions of section 1395e of this title, if the operating costs of inpatient hospital services (as defined in subsection (a)(4)) of a hospital (other than a subsection (d) hospital, as defined in subsection (d)(1)(B) and other than a rehabilitation facility described in subsection (j)(1)) for a cost reporting period subject to this paragraph—"],[1,"(A) are less than or equal to the target amount (as defined in paragraph (3)) for that hospital for that period, the amount of the payment with respect to such operating costs payable under part A on a per discharge or per admission basis (as the case may be) shall be equal to the amount of such operating costs, plus—"],[2,"(i) 15 percent of the amount by which the target amount exceeds the amount of the operating costs, or"],[2,"(ii) 2 percent of the target amount,"],[1,"whichever is less;"],[1,"(B) are greater than the target amount but do not exceed 110 percent of the target amount, the amount of the payment with respect to those operating costs payable under part A on a per discharge basis shall equal the target amount; or"],[1,"(C) are greater than 110 percent of the target amount, the amount of the payment with respect to such operating costs payable under part A on a per discharge or per admission basis (as the case may be) shall be equal to (i) the target amount, plus (ii) in the case of cost reporting periods beginning on or after October 1, 1991, an additional amount equal to 50 percent of the amount by which the operating costs exceed 110 percent of the target amount (except that such additional amount may not exceed 10 percent of the target amount) after any exceptions or adjustments are made to such target amount for the cost reporting period;"],[0,"plus the amount, if any, provided under paragraph (2), except that in no case may the amount payable under this subchapter (other than on the basis of a DRG prospective payment rate determined under subsection (d)) with respect to operating costs of inpatient hospital services exceed the maximum amount payable with respect to such costs pursuant to subsection (a)."],[0,"(2)(A) Except as provided in subparagraph (E), in addition to the payment computed under paragraph (1), in the case of an eligible hospital (described in subparagraph (B)) for a cost reporting period beginning on or after October 1, 1997, the amount of payment on a per discharge basis under paragraph (1) shall be increased by the lesser of—"],[1,"(i) 50 percent of the amount by which the operating costs are less than the expected costs (as defined in subparagraph (D)) for the period; or"],[1,"(ii) 1 percent of the target amount for the period."],[0,"(B) For purposes of this paragraph, an \"eligible hospital\" means with respect to a cost reporting period, a hospital—"],[1,"(i) that has received payments under this subsection for at least 3 full cost reporting periods before that cost reporting period, and"],[1,"(ii) whose operating costs for the period are less than the least of its target amount, its trended costs (as defined in subparagraph (C)), or its expected costs (as defined in subparagraph (D)) for the period."],[0,"(C) For purposes of subparagraph (B)(ii), the term \"trended costs\" means for a hospital cost reporting period ending in a fiscal year—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395ww?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1395ww. Payments to hospitals for inpatient hospital services","tname":"The Public Health and Welfare","by":{"0":"3, 4, 5, 4, 24, 4, 24, 4, 24, 4, 24, 4, 24, 4, 24, 4, 24, 4, 24","1":"passim","2":"17, 7, 8, 9, 1, 2, 3, 10, 11, 13, 3"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","stext":{"head":"§1396. Medicaid and CHIP Payment and Access Commission","paras":[[0,"(a) Establishment"],[0,"There is hereby established the Medicaid and CHIP Payment and Access Commission (in this section referred to as \"MACPAC\")."],[0,"(b) Duties"],[0,"(1) Review of access policies for all States and annual reports"],[1,"MACPAC shall—"],[2,"(A) review policies of the Medicaid program established under this subchapter (in this section referred to as \"Medicaid\") and the State Children's Health Insurance Program established under subchapter XXI (in this section referred to as \"CHIP\") affecting access to covered items and services, including topics described in paragraph (2);"],[2,"(B) make recommendations to Congress, the Secretary, and States concerning such access policies;"],[2,"(C) by not later than March 15 of each year (beginning with 2010), submit a report to Congress containing the results of such reviews and MACPAC's recommendations concerning such policies; and"],[2,"(D) by not later than June 15 of each year (beginning with 2010), submit a report to Congress containing an examination of issues affecting Medicaid and CHIP, including the implications of changes in health care delivery in the United States and in the market for health care services on such programs."],[0,"(2) Specific topics to be reviewed"],[1,"Specifically, MACPAC shall review and assess the following:"],[0,"(A) Medicaid and CHIP payment policies"],[2,"Payment policies under Medicaid and CHIP, including—"],[3,"(i) the factors affecting expenditures for the efficient provision of items and services in different sectors, including the process for updating payments to medical, dental, and health professionals, hospitals, residential and long-term care providers, providers of home and community based services, Federally-qualified health centers and rural health clinics, managed care entities, and providers of other covered items and services;"],[3,"(ii) payment methodologies; and"],[3,"(iii) the relationship of such factors and methodologies to access and quality of care for Medicaid and CHIP beneficiaries (including how such factors and methodologies enable such beneficiaries to obtain the services for which they are eligible, affect provider supply, and affect providers that serve a disproportionate share of low-income and other vulnerable populations)."],[0,"(B) Eligibility policies"],[2,"Medicaid and CHIP eligibility policies, including a determination of the degree to which Federal and State policies provide health care coverage to needy populations."],[0,"(C) Enrollment and retention processes"],[2,"Medicaid and CHIP enrollment and retention processes, including a determination of the degree to which Federal and State policies encourage the enrollment of individuals who are eligible for such programs and screen out individuals who are ineligible, while minimizing the share of program expenses devoted to such processes."],[0,"(D) Coverage policies"],[2,"Medicaid and CHIP benefit and coverage policies, including a determination of the degree to which Federal and State policies provide access to the services enrollees require to improve and maintain their health and functional status."],[0,"(E) Quality of care"],[2,"Medicaid and CHIP policies as they relate to the quality of care provided under those programs, including a determination of the degree to which Federal and State policies achieve their stated goals and interact with similar goals established by other purchasers of health care services."],[0,"(F) Interaction of Medicaid and CHIP payment policies with health care delivery generally"],[2,"The effect of Medicaid and CHIP payment policies on access to items and services for children and other Medicaid and CHIP populations other than under this subchapter or subchapter XXI and the implications of changes in health care delivery in the United States and in the general market for health care items and services on Medicaid and CHIP."],[0,"(G) Interactions with Medicare and Medicaid"],[2,"Consistent with paragraph (11), the interaction of policies under Medicaid and the Medicare program under subchapter XVIII, including with respect to how such interactions affect access to services, payments, and dual eligible individuals."],[0,"(H) Other access policies"],[2,"The effect of other Medicaid and CHIP policies on access to covered items and services, including policies relating to transportation and language barriers and preventive, acute, and long-term services and supports."],[0,"(3) Recommendations and reports of State-specific data"],[1,"MACPAC shall—"],[2,"(A) review national and State-specific Medicaid and CHIP data; and"],[2,"(B) submit reports and recommendations to Congress, the Secretary, and States based on such reviews."],[0,"(4) Creation of early-warning system"],[1,"MACPAC shall create an early-warning system to identify provider shortage areas, as well as other factors that adversely affect, or have the potential to adversely affect, access to care by, or the health care status of, Medicaid and CHIP beneficiaries. MACPAC shall include in the annual report required under paragraph (1)(D) a description of all such areas or problems identified with respect to the period addressed in the report."],[0,"(5) Comments on certain secretarial reports and regulations"],[0,"(A) Certain secretarial reports"],[2,"If the Secretary submits to Congress (or a committee of Congress) a report that is required by law and that relates to access policies, including with respect to payment policies, under Medicaid or CHIP, the Secretary shall transmit a copy of the report to MACPAC. MACPAC shall review the report and, not later than 6 months after the date of submittal of the Secretary's report to Congress, shall submit to the appropriate committees of Congress and the Secretary written comments on such report. Such comments may include such recommendations as MACPAC deems appropriate."],[0,"(B) Regulations"],[2,"MACPAC shall review Medicaid and CHIP regulations and may comment through submission of a report to the appropriate committees of Congress and the Secretary, on any such regulations that affect access, quality, or efficiency of health care."],[0,"(6) Agenda and additional reviews"],[0,"(A) In general"],[2,"MACPAC shall consult periodically with the chairmen and ranking minority members of the appropriate committees of Congress regarding MACPAC's agenda and progress towards achieving the agenda. MACPAC may conduct additional reviews, and submit additional reports to the appropriate committees of Congress, from time to time on such topics relating to the program under this subchapter or subchapter XXI as may be requested by such chairmen and members and as MACPAC deems appropriate."],[0,"(B) Review and reports regarding Medicaid DSH"],[0,"(i) In general"],[3,"MACPAC shall review and submit an annual report to Congress on disproportionate share hospital payments under section 1396r–4 of this title. Each report shall include the information specified in clause (ii)."],[0,"(ii) Required report information"],[3,"Each report required under this subparagraph shall include the following:"],[4,"(I) Data relating to changes in the number of uninsured individuals."],[4,"(II) Data relating to the amount and sources of hospitals' uncompensated care costs, including the amount of such costs that are the result of providing unreimbursed or under-reimbursed services, charity care, or bad debt."],[4,"(III) Data identifying hospitals with high levels of uncompensated care that also provide access to essential community services for low-income, uninsured, and vulnerable populations, such as graduate medical education, and the continuum of primary through quarternary care, including the provision of trauma care and public health services."],[4,"(IV) State-specific analyses regarding the relationship between the most recent State DSH allotment and the projected State DSH allotment for the succeeding year and the data reported under subclauses (I), (II), and (III) for the State."],[0,"(iii) Data"],[3,"Notwithstanding any other provision of law, the Secretary regularly shall provide MACPAC with the most recent State reports and most recent independent certified audits submitted under section 1396r–4(j) of this title, cost reports submitted under subchapter XVIII, and such other data as MACPAC may request for purposes of conducting the reviews and preparing and submitting the annual reports required under this subparagraph."],[0,"(iv) Submission deadlines"],[3,"The first report required under this subparagraph shall be submitted to Congress not later than February 1, 2016. Subsequent reports shall be submitted as part of, or with, each annual report required under paragraph (1)(C) during the period of fiscal years 2017 through 2024."],[0,"(7) Availability of reports"],[1,"MACPAC shall transmit to the Secretary a copy of each report submitted under this subsection and shall make such reports available to the public."],[0,"(8) Appropriate committee of Congress"],[1,"For purposes of this section, the term \"appropriate committees of Congress\" means the Committee on Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate."],[0,"(9) Voting and reporting requirements"],[1,"With respect to each recommendation contained in a report submitted under paragraph (1), each member of MACPAC shall vote on the recommendation, and MACPAC shall include, by member, the results of that vote in the report containing the recommendation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396. Medicaid and CHIP Payment and Access Commission","tname":"The Public Health and Welfare","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 98-21","url":"https://www.govinfo.gov/link/statute/97/152","by":{"0":"3","1":"7"}},{"t":"reg","label":"48 Fed. Reg. 12,526","url":"https://www.govinfo.gov/link/fr/48/12526","by":{"0":"10, 32"}},{"t":"reg","label":"51 Fed. Reg. 16,772","url":"https://www.govinfo.gov/link/fr/51/16772","by":{"0":"12"}},{"t":"reg","label":"51 Fed. Reg. 31,454","url":"https://www.govinfo.gov/link/fr/51/31454","by":{"0":"11, 33","1":"12, 49"}},{"t":"reg","label":"68 Fed. Reg. 27,154","url":"https://www.govinfo.gov/link/fr/68/27154","by":{"0":"14, 15, 42","1":"16","2":"19"}},{"t":"reg","label":"68 Fed. Reg. 45,346","url":"https://www.govinfo.gov/link/fr/68/45346","by":{"0":"15","1":"17","2":"14, 15"}},{"t":"reg","label":"69 Fed. Reg. 28,196","url":"https://www.govinfo.gov/link/fr/69/28196","by":{"0":"15","1":"17"}},{"t":"reg","label":"69 Fed. Reg. 48,916","url":"https://www.govinfo.gov/link/fr/69/48916","by":{"0":"passim","1":"passim","2":"6, 13, 19, 23"}},{"t":"case","label":"Adena Reg’l Med. Ctr. v. Leavitt","cite":"527 F.3d 176","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/527/176/","by":{"1":"7"}},{"t":"case","label":"Alhambra Hosp. v. Thompson","cite":"259 F.3d 1071","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/259/1071/","by":{"1":"11"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27, 29, 44, 50"}},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"549 U.S. 84","y":2006,"id":"2006/05-669","sc":1,"sum":"The Court ruled 7-0 that \"the 6-year statute of limitations in 2415(a) applies only to court actions and not to the administrative proceedings involved in this case.\" The opinion by Justice Samuel Alito relied on the plain meaning of the language in Section 2415(a). The statute used the terms \"action\" and \"complaint\" when referring to the statute of limitations.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Caring Hearts Pers. Home Servs., Inc. v. Burwell","cite":"824 F.3d 968","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/968/","by":{"1":"27"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Cnty. of Maui v. Haw. Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Empire Health Found. for Valley Hosp. Med. Ctr. v. Price","cite":"334 F. Supp. 3d 1134","y":2018,"court":"E.D. Wash.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/334/1134/","by":{"1":"19"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"ar":7,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"ar":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"24, 26"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Heckler v. Redbud Hosp. Dist.","cite":"473 U.S. 1308","y":1985,"url":"https://supreme.justia.com/cases/federal/us/473/1308/","sc":1,"by":{"1":"7"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Int’l Harvester Co. v. Missouri","cite":"234 U.S. 199","y":1914,"id":"scdb/1913-091","sc":1,"sum":"Although the state appellate court may not have referred to the constitutional questions in its opinion, this court cannot regard such silence as a condemnation of the time at, 'or manner in which, those questions were raised; and, if the record shows that they were raised in that court, this court has jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23, 25"}},{"t":"case","label":"Methodist Hosp. of Sacramento v. Shalala","cite":"38 F.3d 1225","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/38/1225/","by":{"1":"6"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"35, 36, 48"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Portland Adventist Med. Ctr. v. Thompson","cite":"399 F.3d 1091","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/399/1091/","by":{"1":"11, 33"}},{"t":"case","label":"Redbud Hosp. Dist. v. Heckler","cite":"1984 WL 2857","y":1984,"court":"N.D. Cal. July 30","by":{"1":"7"}},{"t":"case","label":"Saint Francis Med. Ctr. v. Azar","cite":"894 F.3d 290","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/894/290/","by":{"1":"6"}},{"t":"case","label":"Samaritan Health Ctr. v. Bowen","cite":"646 F. Supp. 343","y":1986,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./646/343/","by":{"1":"8"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"ar":3,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36, 44, 50"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"32, 38"}},{"t":"case","label":"United States v. Cartwright","cite":"411 U.S. 546","y":1973,"id":"1972/71-1665","sc":1,"sum":"Shares in mutual funds can be \"sold\" by the shareholder only back to the fund and only at a set redemption price. Treas. Reg. § 20.2031-8 (b), requiring that such shares be valued for federal estate tax purposes at the current public offering (\"asked\") price, which is determined by adding a load or sales charge to the net asset value, is clearly inconsistent with the Investment Company Act of 1940, and is therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"ar":2,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"23, 24, 26, 47"}},{"t":"case","label":"United States v. Vogel Fertilizer Co.","cite":"455 U.S. 16","y":1982,"id":"1981/80-1251","sc":1,"sum":"The implementing Treasury Regulation is invalid as not being a reasonable interpretation of the statute, which, as indicated by its language, structure, and legislative history, was intended to apply only where each person whose stock is taken into account for purposes of the 80-percent requirement owns stock in each corporation of the group.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Univ. of Wash. Med. Ctr. v. Sebelius","cite":"634 F.3d 1029","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/1029/","by":{"1":"7"}},{"t":"case","label":"Verizon Commc’ns Inc. v. FCC","cite":"535 U.S. 467","y":2002,"id":"2001/00-511","sc":1,"sum":"The Court held that the FCC can require state commissions to set the rates charged by incumbents for leased elements on a forward-looking basis untied to the incumbents' investment and that the FCC can require incumbents to combine elements of their networks at the request of entrants.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Walter O. Boswell Mem’l Hosp. v. Heckler","cite":"749 F.2d 788","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/749/788/","by":{"1":"47"}},{"t":"usc","label":"42 U.S.C. § 1381a","url":"https://www.law.cornell.edu/uscode/text/42/1381a","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1382","url":"https://www.law.cornell.edu/uscode/text/42/1382","subs":["(a)(1)","(c)(7)"],"stext":{"head":"§1382. Eligibility for benefits","paras":[[0,"(a) \"Eligible individual\" defined"],[0,"(1) Each aged, blind, or disabled individual who does not have an eligible spouse and—"],[1,"(A) whose income, other than income excluded pursuant to section 1382a(b) of this title, is at a rate of not more than $1,752 (or, if greater, the amount determined under section 1382f of this title) for the calendar year 1974 or any calendar year thereafter, and"],[1,"(B) whose resources, other than resources excluded pursuant to section 1382b(a) of this title, are not more than (i) in case such individual has a spouse with whom he is living, the applicable amount determined under paragraph (3)(A), or (ii) in case such individual has no spouse with whom he is living, the applicable amount determined under paragraph (3)(B),"],[0,"shall be an eligible individual for purposes of this subchapter."],[0,"(2) Each aged, blind, or disabled individual who has an eligible spouse and—"],[1,"(A) whose income (together with the income of such spouse), other than income excluded pursuant to section 1382a(b) of this title, is at a rate of not more than $2,628 (or, if greater, the amount determined under section 1382f of this title) for the calendar year 1974, or any calendar year thereafter, and"],[1,"(B) whose resources (together with the resources of such spouse), other than resources excluded pursuant to section 1382b(a) of this title, are not more than the applicable amount determined under paragraph (3)(A),"],[0,"shall be an eligible individual for purposes of this subchapter."],[0,"(3)(A) The dollar amount referred to in clause (i) of paragraph (1)(B), and in paragraph (2)(B), shall be $2,250 prior to January 1, 1985, and shall be increased to $2,400 on January 1, 1985, to $2,550 on January 1, 1986, to $2,700 on January 1, 1987, to $2,850 on January 1, 1988, and to $3,000 on January 1, 1989."],[0,"(B) The dollar amount referred to in clause (ii) of paragraph (1)(B), shall be $1,500 prior to January 1, 1985, and shall be increased to $1,600 on January 1, 1985, to $1,700 on January 1, 1986, to $1,800 on January 1, 1987, to $1,900 on January 1, 1988, and to $2,000 on January 1, 1989."],[0,"(b) Amount of benefits"],[0,"(1) The benefit under this subchapter for an individual who does not have an eligible spouse shall be payable at the rate of $1,752 (or, if greater, the amount determined under section 1382f of this title) for the calendar year 1974 and any calendar year thereafter, reduced by the amount of income, not excluded pursuant to section 1382a(b) of this title, of such individual."],[0,"(2) The benefit under this subchapter for an individual who has an eligible spouse shall be payable at the rate of $2,628 (or, if greater, the amount determined under section 1382f of this title) for the calendar year 1974 and any calendar year thereafter, reduced by the amount of income, not excluded pursuant to section 1382a(b) of this title, of such individual and spouse."],[0,"(c) Period for determination of benefits"],[0,"(1) An individual's eligibility for a benefit under this subchapter for a month shall be determined on the basis of the individual's (and eligible spouse's, if any) income, resources, and other relevant characteristics in such month, and, except as provided in paragraphs (2), (3), (4), (5), and (6), the amount of such benefit shall be determined for such month on the basis of income and other characteristics in the first or, if the Commissioner of Social Security so determines, second month preceding such month. Eligibility for and the amount of such benefits shall be redetermined at such time or times as may be provided by the Commissioner of Social Security."],[0,"(2) The amount of such benefit for the month in which an application for benefits becomes effective (or, if the Commissioner of Social Security so determines, for such month and the following month) and for any month immediately following a month of ineligibility for such benefits (or, if the Commissioner of Social Security so determines, for such month and the following month) shall—"],[1,"(A) be determined on the basis of the income of the individual and the eligible spouse, if any, of such individual and other relevant circumstances in such month; and"],[1,"(B) in the case of the first month following a period of ineligibility in which eligibility is restored after the first day of such month, bear the same ratio to the amount of the benefit which would have been payable to such individual if eligibility had been restored on the first day of such month as the number of days in such month including and following the date of restoration of eligibility bears to the total number of days in such month."],[0,"(3) For purposes of this subsection, an increase in the benefit amount payable under subchapter II (over the amount payable in the preceding month, or, at the election of the Commissioner of Social Security, the second preceding month) to an individual receiving benefits under this subchapter shall be included in the income used to determine the benefit under this subchapter of such individual for any month which is—"],[1,"(A) the first month in which the benefit amount payable to such individual under this title is increased pursuant to section 1382f of this title, or"],[1,"(B) at the election of the Commissioner of Social Security, the month immediately following such month."],[0,"(4)(A) Notwithstanding paragraph (3), if the Commissioner of Social Security determines that reliable information is currently available with respect to the income and other circumstances of an individual for a month (including information with respect to a class of which such individual is a member and information with respect to scheduled cost-of-living adjustments under other benefit programs), the benefit amount of such individual under this subchapter for such month may be determined on the basis of such information."],[0,"(B) The Commissioner of Social Security shall prescribe by regulation the circumstances in which information with respect to an event may be taken into account pursuant to subparagraph (A) in determining benefit amounts under this subchapter."],[0,"(5) Notwithstanding paragraphs (1) and (2), any income which is paid to or on behalf of an individual in any month pursuant to (A) a State program funded under part A of subchapter IV, (B) section 672 of this title (relating to foster care assistance), (C) section 1522(e) of title 8 (relating to assistance for refugees), (D) section 501(a) of Public Law 96-422 (relating to assistance for Cuban and Haitian entrants), or (E) section 13 of title 25 (relating to assistance furnished by the Bureau of Indian Affairs), shall be taken into account in determining the amount of the benefit under this subchapter of such individual (and his eligible spouse, if any) only for that month, and shall not be taken into account in determining the amount of the benefit for any other month."],[0,"(6) The dollar amount in effect under subsection (b) as a result of any increase in benefits under this subchapter by reason of section 1382f of this title shall be used to determine the value of any in-kind support and maintenance required to be taken into account in determining the benefit payable under this subchapter to an individual (and the eligible spouse, if any, of the individual) for the 1st 2 months for which the increase in benefits applies."],[0,"(7) For purposes of this subsection, an application of an individual for benefits under this subchapter shall be effective on the later of—"],[1,"(A) the first day of the month following the date such application is filed, or"],[1,"(B) the first day of the month following the date such individual becomes eligible for such benefits with respect to such application."],[0,"(8) The Commissioner of Social Security may waive the limitations specified in subparagraphs (A) and (B) of subsection (e)(1) on an individual's eligibility and benefit amount for a month (to the extent either such limitation is applicable by reason of such individual's presence throughout such month in a hospital, extended care facility, nursing home, or intermediate care facility) if such waiver would promote the individual's removal from such institution or facility. Upon waiver of such limitations, the Commissioner of Social Security shall apply, to the month preceding the month of removal, or, if the Commissioner of Social Security so determines, the two months preceding the month of removal, the benefit rate that is appropriate to such individual's living arrangement subsequent to his removal from such institution or facility."],[0,"(9)(A) Notwithstanding paragraphs (1) and (2), any nonrecurring income which is paid to an individual in the first month of any period of eligibility shall be taken into account in determining the amount of the benefit under this subchapter of such individual (and his eligible spouse, if any) only for that month, and shall not be taken into account in determining the amount of the benefit for any other month."],[0,"(B) For purposes of subparagraph (A), payments to an individual in varying amounts from the same or similar source for the same or similar purpose shall not be considered to be nonrecurring income."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1382?type=usc&year=mostrecent&link-type=html"},"head":"§1382. Eligibility for benefits","tname":"The Public Health and Welfare","by":{"1":"15, 40, 41","2":"18, 10"}},{"t":"usc","label":"42 U.S.C. § 1382a","url":"https://www.law.cornell.edu/uscode/text/42/1382a","subs":["(b)"],"by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1382b","url":"https://www.law.cornell.edu/uscode/text/42/1382b","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1382c","url":"https://www.law.cornell.edu/uscode/text/42/1382c","subs":["(a)(1)"],"stext":{"head":"§1382c. Definitions","paras":[[0,"(a)(1) For purposes of this subchapter, the term \"aged, blind, or disabled individual\" means an individual who—"],[1,"(A) is 65 years of age or older, is blind (as determined under paragraph (2)), or is disabled (as determined under paragraph (3)), and"],[1,"(B)(i) is a resident of the United States, and is either (I) a citizen or (II) an alien lawfully admitted for permanent residence or otherwise permanently residing in the United States under color of law (including any alien who is lawfully present in the United States as a result of the application of the provisions of section 1182(d)(5) of title 8), or"],[1,"(ii) is a child who is a citizen of the United States, and who is living with a parent of the child who is a member of the Armed Forces of the United States assigned to permanent duty ashore outside the United States."],[0,"(2) An individual shall be considered to be blind for purposes of this subchapter if he has central visual acuity of 20/200 or less in the better eye with the use of a correcting lens. An eye which is accompanied by a limitation in the fields of vision such that the widest diameter of the visual field subtends an angle no greater than 20 degrees shall be considered for purposes of the first sentence of this subsection as having a central visual acuity of 20/200 or less. An individual shall also be considered to be blind for purposes of this subchapter if he is blind as defined under a State plan approved under subchapter X or XVI as in effect for October 1972 and received aid under such plan (on the basis of blindness) for December 1973, so long as he is continuously blind as so defined."],[0,"(3)(A) Except as provided in subparagraph (C), an individual shall be considered to be disabled for purposes of this subchapter if he is unable to engage in any substantial gainful activity by reason of any medically determinable physical or mental impairment which can be expected to result in death or which has lasted or can be expected to last for a continuous period of not less than twelve months."],[0,"(B) For purposes of subparagraph (A), an individual shall be determined to be under a disability only if his physical or mental impairment or impairments are of such severity that he is not only unable to do his previous work but cannot, considering his age, education, and work experience, engage in any other kind of substantial gainful work which exists in the national economy, regardless of whether such work exists in the immediate area in which he lives, or whether a specific job vacancy exists for him, or whether he would be hired if he applied for work. For purposes of the preceding sentence (with respect to any individual), \"work which exists in the national economy\" means work which exists in significant numbers either in the region where such individual lives or in several regions of the country."],[0,"(C)(i) An individual under the age of 18 shall be considered disabled for the purposes of this subchapter if that individual has a medically determinable physical or mental impairment, which results in marked and severe functional limitations, and which can be expected to result in death or which has lasted or can be expected to last for a continuous period of not less than 12 months."],[0,"(ii) Notwithstanding clause (i), no individual under the age of 18 who engages in substantial gainful activity (determined in accordance with regulations prescribed pursuant to subparagraph (E)) may be considered to be disabled."],[0,"(D) For purposes of this paragraph, a physical or mental impairment is an impairment that results from anatomical, physiological, or psychological abnormalities which are demonstrable by medically acceptable clinical and laboratory diagnostic techniques."],[0,"(E) The Commissioner of Social Security shall by regulations prescribe the criteria for determining when services performed or earnings derived from services demonstrate an individual's ability to engage in substantial gainful activity. In determining whether an individual is able to engage in substantial gainful activity by reason of his earnings, where his disability is sufficiently severe to result in a functional limitation requiring assistance in order for him to work, there shall be excluded from such earnings an amount equal to the cost (to such individual) of any attendant care services, medical devices, equipment, prostheses, and similar items and services (not including routine drugs or routine medical services unless such drugs or services are necessary for the control of the disabling condition) which are necessary (as determined by the Commissioner of Social Security in regulations) for that purpose, whether or not such assistance is also needed to enable him to carry out his normal daily functions; except that the amounts to be excluded shall be subject to such reasonable limits as the Commissioner of Social Security may prescribe. Notwithstanding the provisions of subparagraph (B), an individual whose services or earnings meet such criteria shall be found not to be disabled. The Commissioner of Social Security shall make determinations under this subchapter with respect to substantial gainful activity, without regard to the legality of the activity."],[0,"(F) Notwithstanding the provisions of subparagraphs (A) through (E), an individual shall also be considered to be disabled for purposes of this subchapter if he is permanently and totally disabled as defined under a State plan approved under subchapter XIV or XVI as in effect for October 1972 and received aid under such plan (on the basis of disability) for December 1973 (and for at least one month prior to July 1973), so long as he is continuously disabled as so defined."],[0,"(G) In determining whether an individual's physical or mental impairment or impairments are of a sufficient medical severity that such impairment or impairments could be the basis of eligibility under this section, the Commissioner of Social Security shall consider the combined effect of all of the individual's impairments without regard to whether any such impairment, if considered separately, would be of such severity. If the Commissioner of Social Security does find a medically severe combination of impairments, the combined impact of the impairments shall be considered throughout the disability determination process."],[0,"(H)(i) In making determinations with respect to disability under this subchapter, the provisions of sections 421(h), 421(k), and 423(d)(5) of this title shall apply in the same manner as they apply to determinations of disability under subchapter II."],[0,"(ii)(I) Not less frequently than once every 3 years, the Commissioner shall review in accordance with paragraph (4) the continued eligibility for benefits under this subchapter of each individual who has not attained 18 years of age and is eligible for such benefits by reason of an impairment (or combination of impairments) which is likely to improve (or, at the option of the Commissioner, which is unlikely to improve)."],[0,"(II) A representative payee of a recipient whose case is reviewed under this clause shall present, at the time of review, evidence demonstrating that the recipient is, and has been, receiving treatment, to the extent considered medically necessary and available, of the condition which was the basis for providing benefits under this subchapter."],[0,"(III) If the representative payee refuses to comply without good cause with the requirements of subclause (II), the Commissioner of Social Security shall, if the Commissioner determines it is in the best interest of the individual, promptly suspend payment of benefits to the representative payee, and provide for payment of benefits to an alternative representative payee of the individual or, if the interest of the individual under this subchapter would be served thereby, to the individual."],[0,"(IV) Subclause (II) shall not apply to the representative payee of any individual with respect to whom the Commissioner determines such application would be inappropriate or unnecessary. In making such determination, the Commissioner shall take into consideration the nature of the individual's impairment (or combination of impairments). Section 1383(c) of this title shall not apply to a finding by the Commissioner that the requirements of subclause (II) should not apply to an individual's representative payee."],[0,"(iii) If an individual is eligible for benefits under this subchapter by reason of disability for the month preceding the month in which the individual attains the age of 18 years, the Commissioner shall redetermine such eligibility—"],[1,"(I) by applying the criteria used in determining initial eligibility for individuals who are age 18 or older; and"],[1,"(II) either during the 1-year period beginning on the individual's 18th birthday or, in lieu of a continuing disability review, whenever the Commissioner determines that an individual's case is subject to a redetermination under this clause."],[0,"With respect to any redetermination under this clause, paragraph (4) shall not apply."],[0,"(iv)(I) Except as provided in subclause (VI), not later than 12 months after the birth of an individual, the Commissioner shall review in accordance with paragraph (4) the continuing eligibility for benefits under this subchapter by reason of disability of such individual whose low birth weight is a contributing factor material to the Commissioner's determination that the individual is disabled."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1382c?type=usc&year=mostrecent&link-type=html"},"head":"§1382c. Definitions","tname":"The Public Health and Welfare","by":{"1":"40","2":"18"}},{"t":"usc","label":"42 U.S.C. § 1382e","url":"https://www.law.cornell.edu/uscode/text/42/1382e","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1382h","url":"https://www.law.cornell.edu/uscode/text/42/1382h","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1382j","url":"https://www.law.cornell.edu/uscode/text/42/1382j","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1383c","url":"https://www.law.cornell.edu/uscode/text/42/1383c","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1383d","url":"https://www.law.cornell.edu/uscode/text/42/1383d","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)"],"stext":{"head":"§1396d. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Medical assistance"],[0,"The term \"medical assistance\" means payment of part or all of the cost of the following care and services or the care and services themselves, or both (if provided in or after the third month before the month in which the recipient makes application for assistance or, in the case of medicare cost-sharing with respect to a qualified medicare beneficiary described in subsection (p)(1), if provided after the month in which the individual becomes such a beneficiary) for individuals, and, with respect to physicians' or dentists' services, at the option of the State, to individuals (other than individuals with respect to whom there is being paid, or who are eligible, or would be eligible if they were not in a medical institution, to have paid with respect to them a State supplementary payment and are eligible for medical assistance equal in amount, duration, and scope to the medical assistance made available to individuals described in section 1396a(a)(10)(A) of this title) not receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A of subchapter IV, and with respect to whom supplemental security income benefits are not being paid under subchapter XVI, who are—"],[1,"(i) under the age of 21, or, at the option of the State, under the age of 20, 19, or 18 as the State may choose,"],[1,"(ii) relatives specified in section 606(b)(1) 1 of this title with whom a child is living if such child is (or would, if needy, be) a dependent child under part A of subchapter IV,"],[1,"(iii) 65 years of age or older,"],[1,"(iv) blind, with respect to States eligible to participate in the State plan program established under subchapter XVI,"],[1,"(v) 18 years of age or older and permanently and totally disabled, with respect to States eligible to participate in the State plan program established under subchapter XVI,"],[1,"(vi) persons essential (as described in the second sentence of this subsection) to individuals receiving aid or assistance under State plans approved under subchapter I, X, XIV, or XVI,"],[1,"(vii) blind or disabled as defined in section 1382c of this title, with respect to States not eligible to participate in the State plan program established under subchapter XVI,"],[1,"(viii) pregnant women,"],[1,"(ix) individuals provided extended benefits under section 1396r–6 of this title,"],[1,"(x) individuals described in section 1396a(u)(1) of this title,"],[1,"(xi) individuals described in section 1396a(z)(1) of this title,"],[1,"(xii) employed individuals with a medically improved disability (as defined in subsection (v)),"],[1,"(xiii) individuals described in section 1396a(aa) of this title,"],[1,"(xiv) individuals described in section 1396a(a)(10)(A)(i)(VIII) or 1396a(a)(10)(A)(i)(IX) of this title,"],[1,"(xv) individuals described in section 1396a(a)(10)(A)(ii)(XX) of this title,"],[1,"(xvi) individuals described in section 1396a(ii) of this title, or"],[1,"(xvii) individuals who are eligible for home and community-based services under needs-based criteria established under paragraph (1)(A) of section 1396n(i) of this title, or who are eligible for home and community-based services under paragraph (6) of such section, and who will receive home and community-based services pursuant to a State plan amendment under such subsection,"],[0,"but whose income and resources are insufficient to meet all of such cost—"],[1,"(1) inpatient hospital services (other than services in an institution for mental diseases);"],[1,"(2)(A) outpatient hospital services, (B) consistent with State law permitting such services, rural health clinic services (as defined in subsection (l)(1)) and any other ambulatory services which are offered by a rural health clinic (as defined in subsection (l)(1)) and which are otherwise included in the plan, and (C) Federally-qualified health center services (as defined in subsection (l)(2)) and any other ambulatory services offered by a Federally-qualified health center and which are otherwise included in the plan;"],[1,"(3)(A) other laboratory and X-ray services; and"],[1,"(B) in vitro diagnostic products (as defined in section 809.3(a) of title 21, Code of Federal Regulations) administered during any portion of the emergency period defined in paragraph (1)(B) of section 1320b–5(g) of this title beginning on or after March 18, 2020, for the detection of SARS–CoV–2 or the diagnosis of the virus that causes COVID–19, and the administration of such in vitro diagnostic products;"],[1,"(4)(A) nursing facility services (other than services in an institution for mental diseases) for individuals 21 years of age or older; (B) early and periodic screening, diagnostic, and treatment services (as defined in subsection (r)) for individuals who are eligible under the plan and are under the age of 21; (C) family planning services and supplies furnished (directly or under arrangements with others) to individuals of child-bearing age (including minors who can be considered to be sexually active) who are eligible under the State plan and who desire such services and supplies; and 2 (D) counseling and pharmacotherapy for cessation of tobacco use by pregnant women (as defined in subsection (bb)); and 2 (E) during the period beginning on March 11, 2021, and ending on the last day of the first calendar quarter that begins one year after the last day of the emergency period described in section 1320b–5(g)(1)(B) of this title, a COVID–19 vaccine and administration of the vaccine; and (F) during the period beginning on March 11, 2021, and ending on the last day of the first calendar quarter that begins one year after the last day of the emergency period described in section 1320b–5(g)(1)(B) of this title, testing and treatments for COVID–19, including specialized equipment and therapies (including preventive therapies), and, without regard to the requirements of section 1396a(a)(10)(B) of this title (relating to comparability), in the case of an individual who is diagnosed with or presumed to have COVID–19, during the period such individual has (or is presumed to have) COVID–19, the treatment of a condition that may seriously complicate the treatment of COVID–19, if otherwise covered under the State plan (or waiver of such plan);"],[1,"(5)(A) physicians' services furnished by a physician (as defined in section 1395x(r)(1) of this title), whether furnished in the office, the patient's home, a hospital, or a nursing facility, or elsewhere, and (B) medical and surgical services furnished by a dentist (described in section 1395x(r)(2) of this title) to the extent such services may be performed under State law either by a doctor of medicine or by a doctor of dental surgery or dental medicine and would be described in clause (A) if furnished by a physician (as defined in section 1395x(r)(1) of this title);"],[1,"(6) medical care, or any other type of remedial care recognized under State law, furnished by licensed practitioners within the scope of their practice as defined by State law;"],[1,"(7) home health care services;"],[1,"(8) private duty nursing services;"],[1,"(9) clinic services furnished by or under the direction of a physician, without regard to whether the clinic itself is administered by a physician, including such services furnished outside the clinic by clinic personnel to an eligible individual who does not reside in a permanent dwelling or does not have a fixed home or mailing address;"],[1,"(10) dental services;"],[1,"(11) physical therapy and related services;"],[1,"(12) prescribed drugs, dentures, and prosthetic devices; and eyeglasses prescribed by a physician skilled in diseases of the eye or by an optometrist, whichever the individual may select;"],[1,"(13) other diagnostic, screening, preventive, and rehabilitative services, including—"],[2,"(A) any clinical preventive services that are assigned a grade of A or B by the United States Preventive Services Task Force;"],[2,"(B) with respect to an adult individual, approved vaccines recommended by the Advisory Committee on Immunization Practices (an advisory committee established by the Secretary, acting through the Director of the Centers for Disease Control and Prevention) and their administration; and"],[2,"(C) any medical or remedial services (provided in a facility, a home, or other setting) recommended by a physician or other licensed practitioner of the healing arts within the scope of their practice under State law, for the maximum reduction of physical or mental disability and restoration of an individual to the best possible functional level;"],[1,"(14) inpatient hospital services and nursing facility services for individuals 65 years of age or over in an institution for mental diseases;"],[1,"(15) services in an intermediate care facility for the mentally retarded (other than in an institution for mental diseases) for individuals who are determined, in accordance with section 1396a(a)(31) of this title, to be in need of such care;"],[1,"(16)(A) effective January 1, 1973, inpatient psychiatric hospital services for individuals under age 21, as defined in subsection (h), and, (B) for individuals receiving services described in subparagraph (A), early and periodic screening, diagnostic, and treatment services (as defined in subsection (r)), whether or not such screening, diagnostic, and treatment services are furnished by the provider of the services described in such subparagraph;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396d?type=usc&year=mostrecent&link-type=html"},"head":"§1396d. Definitions","tname":"The Public Health and Welfare","by":{"1":"39","2":"9"}},{"t":"law","label":"Pub. L. No. 97-248","url":"https://www.govinfo.gov/link/statute/96/324","by":{"1":"7"}},{"t":"reg","label":"20 C.F.R. § 416.414","url":"https://www.ecfr.gov/current/title-20/section-416.414","by":{"1":"15"}},{"t":"reg","label":"42 C.F.R. § 400.202","url":"https://www.ecfr.gov/current/title-42/section-400.202","by":{"1":"43"}},{"t":"reg","label":"42 C.F.R. § 412.106","url":"https://www.ecfr.gov/current/title-42/section-412.106","subs":["(a)(1)(ii)","(b)","(b)(2)(i)","(b)(4)(i)"],"by":{"1":"31, 39, 41, 17, 40, 42"}},{"t":"reg","label":"42 C.F.R. § 423.773","url":"https://www.ecfr.gov/current/title-42/section-423.773","subs":["(c)(1)(ii)"],"by":{"1":"41"}},{"t":"reg","label":"49 Fed. Reg. 234","url":"https://www.govinfo.gov/link/fr/49/234","by":{"1":"7"}},{"t":"reg","label":"75 Fed. Reg. 50,042","url":"https://www.govinfo.gov/link/fr/75/50042","by":{"1":"15, 39, 40","2":"10, 11"}},{"t":"case","label":"Pls.’ Opp. to Def’s. Cross-Motion for S.J., Catholic Health Initiatives Iowa, Corp. v. Sebelius","cite":"841 F. Supp. 2d 270","y":2012,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/841/270/","by":{"1":"33"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cnty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"(I) Cases—Continued: Deaconess Health Servs. Corp. v. Shalala","cite":"912 F. Supp. 438","y":1995,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./912/438/","sum":"Construing “entitled to” in Medicare fraction as 2004 rule does.","sumSrc":"brief:2","by":{"2":"8"}},{"t":"case","label":"Ragsdale v. Wolverine World Wide, Inc.","cite":"535 U.S. 81","y":2002,"id":"2001/00-6029","sc":1,"sum":"The Court held that the regulation is contrary to the FMLA and beyond the Secretary of Labor's authority. Among other findings, Justice Kennedy reasoned that the regulation amended the FMLA's most fundamental substantive guarantee, the 12-week leave entitlement, and thus undermined Congress's balance of the needs of families and the interests of employers.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Sanchez v. Mayorkas","cite":"141 S. Ct. 1809","y":2021,"id":"2020/20-315","sc":1,"sum":"An individual who entered the United States unlawfully is not eligible to become a lawful permanent resident under 8 U.S.C. §1255 even if the United States has granted the individual temporary protected status.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6, 12"}},{"t":"case","label":"Schweiker v. Gray Panthers","cite":"453 U.S. 34","y":1981,"id":"1980/80-756","sc":1,"sum":"The regulations at issue are consistent with the statutory scheme and are reasonable exercises of the authority delegated to the Secretary. Pp. 43-50. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Schweiker v. Hansen","cite":"450 U.S. 785","y":1981,"id":"1980/80-1162","sc":1,"sum":"Under § 202 (g) (1) (D) of the Social Security Act, \"mother's insurance benefits\" are available only to one who, among other qualifications, \"has filed application.\" An implementing regulation provides that only written applications satisfy this requirement. A Social Security Administration (SSA) field representative erroneously told respondent that she was not entitled to such benefits. And contrary to instructions …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Southwest Consulting 2004 DSH Dual Eligible Days Grp. v. Blue Cross Blue Shield Ass’n","cite":"2010 WL 4214212","y":2010,"court":"P.R.R.B. June 14","by":{"2":"20"}},{"t":"law","label":"Pub. L. No. 109-171","url":"https://www.govinfo.gov/link/plaw/109/public/171","by":{"2":"15"}},{"t":"usc","label":"42 U.S.C. § 1395j","url":"https://www.law.cornell.edu/uscode/text/42/1395j","by":{"2":"6"}},{"t":"usc","label":"42 U.S.C. § 1395hh","url":"https://www.law.cornell.edu/uscode/text/42/1395hh","subs":["(a)"],"by":{"2":"21"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"2":"23"}},{"t":"usc","label":"42 U.S.C. § 1315","url":"https://www.law.cornell.edu/uscode/text/42/1315","subs":["(a)(2)"],"by":{"2":"14, 14"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","by":{"2":"9, 18"}}]};